    ('85202ddc-8f85-5010-a33d-3d33275787fc'::uuid, 'Quiz — Question fermée, question ouverte, question indirecte', 'Allemand', '3e', 'La phrase interrogative', 'ea7322c5-16ef-5919-a640-e14fc45f23d1'::uuid),
