    ('77627871-5522-5b4f-83d4-d02894a1009e'::uuid, 'Quiz — La conjonction envoie le verbe à la fin', 'Allemand', '3e', 'La phrase subordonnée', '9b20cc93-2a30-5463-b60c-76a66a3eeddb'::uuid),
    ('bd616e70-1a9f-569b-9bff-fb8f2bef033c'::uuid, 'Quiz — Le genre vient d’avant, le cas vient d’après', 'Allemand', '3e', 'La phrase subordonnée relative', 'b2459643-4739-5c0a-a5ee-a8b7d88f3a3e'::uuid),
    ('714581be-3b83-58a5-b16b-7d2c38e179e7'::uuid, 'Quiz — werden + participe II, et le fameux worden', 'Allemand', '3e', 'La phrase à la voix passive', '45a2333c-b3eb-598e-9ad0-0a834483ee06'::uuid),
    ('632031fc-a5a4-5119-87ec-3710908c2002'::uuid, 'Quiz — zu + infinitif, et les cas où zu disparaît', 'Allemand', '3e', 'La proposition infinitive', 'ab4ef41c-2de2-5b1a-aa43-4396f1f27b79'::uuid),
    ('18b9e596-ad03-59ee-aa46-4a3e23968004'::uuid, 'Quiz — der, die, das — ein, eine, ein', 'Allemand', '3e', 'Les déterminants définis et indéfinis sujets', 'f9c72d4b-3ff1-5428-a958-6a145acbb8d6'::uuid),
    ('398a4f56-0ce8-5bf3-85b1-4e8a3f4dc021'::uuid, 'Quiz — Quatre cas, deux familles de déterminants', 'Allemand', '3e', 'Les déterminants et leurs déclinaisons', 'd03c28c0-76c1-5de5-9027-b9f3cb2097ee'::uuid),
    ('b63d13c0-619c-5930-8a44-b67baf5b1d81'::uuid, 'Quiz — ich, mich, mir — et l’ordre des pronoms', 'Allemand', '3e', 'Les pronoms personnels', 'dc927928-e2ae-5ed5-8299-f5a120243029'::uuid),
    ('46d4c2a0-8c09-56e7-840b-b224b3e46d63'::uuid, 'Quiz — dieser, jener — et le der qui montre du doigt', 'Allemand', '3e', 'Les pronoms démonstratifs', '59e4d56e-c40b-5576-a527-b3d0c4046076'::uuid),
    ('90c66fce-aa72-5529-9be6-b360bd034afc'::uuid, 'Quiz — Cinq façons de faire un pluriel', 'Allemand', '3e', 'Le pluriel des noms', '9377153c-8eff-5592-a0ea-d2f9a806af61'::uuid),
    ('a3b038a8-1f52-5e56-b38f-661d07e1b8f5'::uuid, 'Quiz — Après sein, werden et bleiben : rien ne bouge', 'Allemand', '3e', 'L’adjectif attribut', '1113b494-1fd9-51d7-b238-dd1e6a9095de'::uuid),
    ('9a3a1905-e380-5abc-8d39-d91e92e4acb8'::uuid, 'Quiz — Faible, mixte, forte : qui porte la marque du cas', 'Allemand', '3e', 'L’adjectif épithète et ses déclinaisons', 'cf345f35-9886-5e0f-8863-8c9d56b16527'::uuid),
    ('d202dead-505d-5bfc-acc1-61b0faacd912'::uuid, 'Quiz — sein ou ihr : c’est le possesseur qui décide', 'Allemand', '3e', 'L’adjectif possessif', 'e310d32c-a782-5b88-8b54-a1b81e6ec893'::uuid),
    ('961080c8-c1ff-563f-b68f-7844c76d975b'::uuid, 'Quiz — Peters Auto, das Auto des Vaters, das Auto von Peter', 'Allemand', '3e', 'Le génitif saxon', 'cf92e180-5143-508f-8850-7df3f4de3f81'::uuid),
    ('7d2bae92-f09b-5876-9ac0-227abc56568c'::uuid, 'Quiz — -er, als, so… wie', 'Allemand', '3e', 'Le comparatif', '604a264d-3149-5f41-9da5-25f4582c6246'::uuid),
    ('78af3bfd-32c3-5fdd-9537-786513c895c7'::uuid, 'Quiz — am schnellsten ou der schnellste', 'Allemand', '3e', 'Le superlatif', 'b21f3a77-ffa4-553c-82e3-4131d3bb56f8'::uuid),
    ('faf0e499-88c9-5851-a4eb-d3dc72420718'::uuid, 'Quiz — durch, für, gegen, ohne, um', 'Allemand', '3e', 'Les prépositions suivies de l’accusatif', '205a3cf0-0991-5989-b069-dd5be6391a5d'::uuid),
    ('24da36a6-025e-566a-a983-9588143da21f'::uuid, 'Quiz — aus, bei, mit, nach, seit, von, zu', 'Allemand', '3e', 'Les prépositions suivies du datif', '48c2300c-2f32-5611-bca2-fdbcaa17b2bf'::uuid),
    ('40b9ec35-d46d-57f8-bc72-9ed608b5dfd1'::uuid, 'Quiz — wo ? datif — wohin ? accusatif', 'Allemand', '3e', 'Les prépositions mixtes', 'b7099ecf-ef02-50a6-a2df-0cb4356cf908'::uuid),
    ('042eb577-a6c3-5ee9-812d-62bf50045df6'::uuid, 'Quiz — Cinq mots qui ne touchent pas à l’ordre des mots', 'Allemand', '3e', 'Les conjonctions de coordination', '1634c6f6-b1a7-5e1f-9f49-1ad8a294521f'::uuid),
    ('929714ca-d38c-5833-906b-fbd5b017287f'::uuid, 'Quiz — wo, wohin, woher — trois questions, trois constructions', 'Allemand', '3e', 'Les compléments de lieu (locatif / directionnel)', '4710ab3d-f87b-5b9b-aad0-771afc0c4ea3'::uuid),
    ('e519912f-9dab-5b64-8363-4b9049b60a99'::uuid, 'Quiz — am, im, um — et l’accusatif sans préposition', 'Allemand', '3e', 'Les compléments de temps', '48a373b9-3737-54d9-98e8-c698dbe0c94b'::uuid),
    ('58c0acea-592c-566e-9bd1-d2c6df4c8c14'::uuid, 'Quiz — sein, haben, werden : trois verbes, six emplois', 'Allemand', '3e', 'Les auxiliaires', 'c94c9e49-2814-568b-9ed9-8f0a020296a6'::uuid),
    ('144b1215-3f83-5520-b96b-21d2d4c7dd33'::uuid, 'Quiz — Trois formes à retenir par verbe', 'Allemand', '3e', 'Les verbes faibles et les verbes forts', '6f29aef3-72b7-561a-bd92-a9de52f11212'::uuid),
    ('3d223955-2ecb-5a62-bb2e-77240ae441ec'::uuid, 'Quiz — Six verbes qui changent le sens de la phrase', 'Allemand', '3e', 'Les verbes de modalité', 'ecb16975-6d27-51a7-a68c-94ff9ba9dbbf'::uuid),
    ('2262badd-8fd2-53fc-a855-123ee0cd4b5c'::uuid, 'Quiz — Le préverbe part à la fin — sauf quand il ne part pas', 'Allemand', '3e', 'Les verbes à préverbe séparable', '6f26f515-cf29-50cd-8f19-594fbde46215'::uuid),
    ('ea5747a4-89ec-5daf-be9c-846ea8fabecc'::uuid, 'Quiz — sich, à l’accusatif ou au datif', 'Allemand', '3e', 'Les verbes pronominaux', '1bb7fe37-26b3-5d10-867a-f8b62c991a2e'::uuid),
    ('da650db0-9662-5d6b-a422-755348cf21b9'::uuid, 'Quiz — Un seul présent, et il dit aussi le futur', 'Allemand', '3e', 'L’indicatif présent', '2a5af4a6-be85-5c2f-9ba8-2fec9391136e'::uuid),
    ('c6003b04-cec0-5d30-a914-f33dd58de659'::uuid, 'Quiz — Le passé de l’écrit et du récit', 'Allemand', '3e', 'Le prétérit', '44272d99-d63c-587c-91cc-9918b56bef30'::uuid),
    ('824b2b34-15d9-54fb-bad4-6b8a170baeb4'::uuid, 'Quiz — Le passé qu’on parle', 'Allemand', '3e', 'Le parfait', '5ae48255-9691-5d2a-bb4d-4a6c640533af'::uuid),
    ('c224b106-f992-5af0-8990-d0d991f64487'::uuid, 'Quiz — werden + infinitif, et le présent qui suffit souvent', 'Allemand', '3e', 'Le futur', 'fc5dce56-d2af-5573-bd5e-998552e5bbac'::uuid),
    ('3afe8e68-f0c5-5848-ac9c-276ad4d40aa4'::uuid, 'Quiz — Trois personnes, trois formes', 'Allemand', '3e', 'L’impératif', '27151ab8-8829-5204-b5c7-b7fcdec7dced'::uuid),
    ('71cfd74e-13d7-59dc-9d4a-21ce8079d39f'::uuid, 'Quiz — würde, hätte, wäre : l’irréel et la politesse', 'Allemand', '3e', 'Le subjonctif II présent', '4565f5c2-f9fd-509c-aa58-feb77491f1ff'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('4df1be15-7e49-5a81-a407-48b2c251a76f'::uuid, '66af46a0-3965-5cf3-a2ed-9449c427e7e4'::uuid, 'Devant une subordonnée introduite par « dass », la virgule est…', 'mcq', '["Obligatoire","Facultative","Interdite","Remplacée par un tiret"]'::jsonb, 0, 'La virgule allemande sépare des propositions : *Ich weiß, dass er kommt.*', 1),
    ('eb13d52a-cced-5221-b308-04f4558f9618'::uuid, '66af46a0-3965-5cf3-a2ed-9449c427e7e4'::uuid, 'En allemand, on met une virgule devant « und » dans une énumération.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Pas de virgule devant *und* ni *oder* ; mais elle est obligatoire devant *aber*, *sondern* et *denn*.', 2),
    ('a7595f64-20b2-5e6c-98db-6503f2644e09'::uuid, '66af46a0-3965-5cf3-a2ed-9449c427e7e4'::uuid, 'Comment s’écrivent les guillemets allemands ?', 'mcq', '["En bas à l’ouverture, en haut à la fermeture","Avec des chevrons, comme en français","Les deux en haut, comme en anglais","Ils n’existent pas"]'::jsonb, 0, '*Er sagt: „Ich komme.“* — et deux-points avant le discours direct.', 3),
    ('37932cfb-4d50-51a8-8211-a1023794f701'::uuid, '66af46a0-3965-5cf3-a2ed-9449c427e7e4'::uuid, 'Quel groupe infinitif exige une virgule ?', 'mcq', '["Celui introduit par um… zu","Tout groupe contenant zu","Aucun groupe infinitif","Seulement celui introduit par dass"]'::jsonb, 0, '*Ich lerne, um zu bestehen.* Idem pour *ohne… zu* et *statt… zu*.', 4),
    ('37314a55-9e6d-518d-8577-3b8a6352de57'::uuid, '66af46a0-3965-5cf3-a2ed-9449c427e7e4'::uuid, 'Un adjectif substantivé prend la majuscule.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*das Wichtigste*, *das Neue* : dès qu’un mot devient nom, il prend la majuscule.', 5),
    ('5bc8ffa3-0333-5a39-bffa-7e59d40d4197'::uuid, '66af46a0-3965-5cf3-a2ed-9449c427e7e4'::uuid, 'Qu’est-ce qui distingue « Sie » de « sie » à l’écrit ?', 'mcq', '["La majuscule du vouvoiement","L’accent sur le e","Rien du tout","La place dans la phrase"]'::jsonb, 0, 'Le *Sie* de politesse et ses formes (*Ihnen*, *Ihr*) gardent la majuscule.', 6),
    ('0e66a30d-576f-5359-8286-9a37bf8ca18a'::uuid, '66af46a0-3965-5cf3-a2ed-9449c427e7e4'::uuid, 'Après une voyelle brève, on écrit…', 'mcq', '["ss, comme dans Fluss et dass","ß, comme dans Fluß et daß","un s simple","sz"]'::jsonb, 0, '*ß* est réservé aux voyelles longues et aux diphtongues : *Straße*, *heißen*.', 7),
    ('b35309fc-da6c-5517-b26a-fa6c984dc605'::uuid, '66af46a0-3965-5cf3-a2ed-9449c427e7e4'::uuid, 'Une subordonnée enchâssée dans la principale est encadrée de deux virgules.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Das Buch, das ich lese, ist spannend.*', 8),
    ('0d29d6ed-fb9c-59a6-9847-51c45067b998'::uuid, 'ed9861af-c75a-5719-b8b1-15e194203423'::uuid, 'Dans une déclarative allemande, le verbe conjugué occupe…', 'mcq', '["La deuxième place","La première place","La dernière place","N’importe quelle place"]'::jsonb, 0, 'La deuxième POSITION, c’est-à-dire le deuxième groupe, pas le deuxième mot.', 1),
    ('4364908e-c5dd-54d9-a042-ba5602f8fddb'::uuid, 'ed9861af-c75a-5719-b8b1-15e194203423'::uuid, '« Heute er geht ins Kino » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Quand un autre élément ouvre la phrase, le sujet passe après le verbe : *Heute geht er…*', 2),
    ('94f1a51f-3308-52fd-ae82-b255bea1c296'::uuid, 'ed9861af-c75a-5719-b8b1-15e194203423'::uuid, 'Où se place l’infinitif dépendant d’un verbe de modalité ?', 'mcq', '["À la fin de la phrase","Juste après le modal","En première position","Avant le sujet"]'::jsonb, 0, 'C’est la parenthèse verbale : *Ich muss heute Abend arbeiten.*', 3),
    ('0f4307b0-ea3e-581b-ab94-d2a56522d568'::uuid, 'ed9861af-c75a-5719-b8b1-15e194203423'::uuid, 'Que signifie l’ordre TeKaMoLo ?', 'mcq', '["Temps, cause, manière, lieu","Temps, lieu, cause, manière","Lieu, temps, cause, manière","Cause, lieu, temps, manière"]'::jsonb, 0, '*Ich fahre morgen wegen der Arbeit mit dem Zug nach München.*', 4),
    ('cb4a49ed-4aee-5ba6-ad1b-baa7648ddbc3'::uuid, 'ed9861af-c75a-5719-b8b1-15e194203423'::uuid, 'Avec deux groupes nominaux, l’ordre est datif puis accusatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ich gebe dem Kind das Buch.* L’ordre s’inverse si l’accusatif est un pronom.', 5),
    ('b1292328-9abb-50e3-936b-8fa1aabf8eb5'::uuid, 'ed9861af-c75a-5719-b8b1-15e194203423'::uuid, 'Comment traduire « Je le donne à l’enfant » ?', 'mcq', '["Ich gebe es dem Kind","Ich gebe dem Kind es","Ich es gebe dem Kind","Ich gebe dem es Kind"]'::jsonb, 0, 'Le pronom accusatif remonte devant le groupe au datif.', 6),
    ('e1c65c9d-1691-5c25-9e79-de1ccbfb2929'::uuid, 'ed9861af-c75a-5719-b8b1-15e194203423'::uuid, 'Dans « Ich stehe um sieben Uhr auf », « auf » est…', 'mcq', '["Le préverbe séparable, rejeté en fin de phrase","Une préposition de lieu","Un adverbe de temps","Une faute de frappe"]'::jsonb, 0, '*aufstehen* : le préverbe ferme la parenthèse verbale.', 7),
    ('4294a18b-f566-57c0-ad8c-6866875d4914'::uuid, 'ed9861af-c75a-5719-b8b1-15e194203423'::uuid, '« Nach Berlin fahre ich morgen » est une phrase correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'N’importe quel groupe peut occuper la première place, tant que le verbe garde la deuxième.', 8),
    ('a6221793-ac17-58d7-b90b-780d59cdda96'::uuid, '85202ddc-8f85-5010-a33d-3d33275787fc'::uuid, 'Dans une question fermée, où se place le verbe conjugué ?', 'mcq', '["En première position","En deuxième position","À la fin de la phrase","Juste après le sujet"]'::jsonb, 0, '*Kommst du morgen?* La réponse attendue est *ja*, *nein* ou *doch*.', 1),
    ('689a9247-2484-5a2a-9366-269205d4f087'::uuid, '85202ddc-8f85-5010-a33d-3d33275787fc'::uuid, 'Dans une question ouverte, le verbe reste en deuxième position.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le mot en *w-* occupe la première place : *Wann kommst du?*', 2),
    ('8021687c-0fc9-5f1c-976d-1e55f916f5a1'::uuid, '85202ddc-8f85-5010-a33d-3d33275787fc'::uuid, 'Quelle est la forme accusative de « wer » ?', 'mcq', '["wen","wem","wessen","was"]'::jsonb, 0, '*Wen siehst du?* — *wem* est le datif, *wessen* le génitif.', 3),
    ('5a8af0c4-b57a-5ccc-9a92-3961e9ce62b5'::uuid, '85202ddc-8f85-5010-a33d-3d33275787fc'::uuid, 'Comment répondre « si ! » à « Du kommst nicht mit? »', 'mcq', '["Doch!","Ja!","Nein!","So!"]'::jsonb, 0, 'Après une question négative, *ja* est impossible : c’est *doch* qui contredit.', 4),
    ('f609a29a-3663-58ed-8218-6ca06036a976'::uuid, '85202ddc-8f85-5010-a33d-3d33275787fc'::uuid, 'Dans une question indirecte, le verbe conjugué se place…', 'mcq', '["À la fin de la subordonnée","En première position","En deuxième position","Devant le sujet"]'::jsonb, 0, '*Ich weiß nicht, wann er kommt.*', 5),
    ('25f6deee-88dc-5178-a863-4d5d53ff192b'::uuid, '85202ddc-8f85-5010-a33d-3d33275787fc'::uuid, 'Le « si » d’une question indirecte se traduit par « wenn ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est *ob* : *Ich frage mich, ob er kommt.* *wenn* introduit une condition ou un moment.', 6),
    ('75cecf35-3067-59ec-9d77-8eef0adeea7f'::uuid, '85202ddc-8f85-5010-a33d-3d33275787fc'::uuid, 'Que demande « wohin » ?', 'mcq', '["La destination d’un déplacement","Le lieu où l’on se trouve","Le lieu d’où l’on vient","La cause"]'::jsonb, 0, '*wo* = sans mouvement, *wohin* = vers où, *woher* = d’où.', 7),
    ('509fbc5c-3915-524c-8293-dea4f7e4d8dc'::uuid, '85202ddc-8f85-5010-a33d-3d33275787fc'::uuid, 'Comment demander « À quoi penses-tu ? »', 'mcq', '["Woran denkst du?","An was denkst du nicht?","Wen denkst du?","Wo denkst du?"]'::jsonb, 0, 'Pour une CHOSE, l’allemand soude *wo(r)-* et la préposition.', 8),
    ('275718cd-0c69-5055-a281-8d132a6ec628'::uuid, 'f7fce0dc-0358-5ab1-93a2-2c1ba919880c'::uuid, 'Comment nier « Ich habe ein Auto » ?', 'mcq', '["Ich habe kein Auto","Ich habe nicht ein Auto","Ich habe nicht Auto","Ich habe ein Auto nicht"]'::jsonb, 0, 'Devant un nom avec *ein* ou sans article, c’est *kein*.', 1),
    ('8badc797-5414-5894-96af-89b1df55cab9'::uuid, 'f7fce0dc-0358-5ab1-93a2-2c1ba919880c'::uuid, 'Comment nier « Ich kenne den Mann » ?', 'mcq', '["Ich kenne den Mann nicht","Ich kenne keinen Mann","Ich kenne den Mann kein","Ich nicht kenne den Mann"]'::jsonb, 0, 'Le nom porte un article défini : la négation est *nicht*, rejetée à droite.', 2),
    ('b07b558e-d0c7-5fa3-99b8-e1e764ede918'::uuid, 'f7fce0dc-0358-5ab1-93a2-2c1ba919880c'::uuid, '« kein » se décline comme « ein » et possède un pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*keine Freunde*, *keinen Kaffee*, *keinem Kind*.', 3),
    ('7d49899d-b16a-5b9d-8f7c-acb456cd26a2'::uuid, 'f7fce0dc-0358-5ab1-93a2-2c1ba919880c'::uuid, 'Où se place « nicht » par rapport à un attribut ?', 'mcq', '["Devant l’attribut","Après l’attribut","En fin de phrase","Devant le sujet"]'::jsonb, 0, '*Das Buch ist nicht interessant.*', 4),
    ('2f025811-e83f-52c8-a9b9-cd60b3b2df7b'::uuid, 'f7fce0dc-0358-5ab1-93a2-2c1ba919880c'::uuid, 'Dans « Ich habe ihn gestern nicht gesehen », « nicht » se place…', 'mcq', '["Devant le participe passé","Après le participe passé","Juste après l’auxiliaire","En première position"]'::jsonb, 0, '*nicht* va le plus à droite possible, mais reste devant le second morceau du verbe.', 5),
    ('962f8e31-cb4b-5fd8-84fa-9f18509f4a31'::uuid, 'f7fce0dc-0358-5ab1-93a2-2c1ba919880c'::uuid, 'En allemand, la double négation renforce la négation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une seule négation suffit : *Ich sehe nichts.* C’est l’espagnol qui double.', 6),
    ('93e8dd95-e428-55b1-80b8-56e8398a1546'::uuid, 'f7fce0dc-0358-5ab1-93a2-2c1ba919880c'::uuid, 'Que signifie « nicht mehr » ?', 'mcq', '["Ne… plus","Pas encore","Jamais","Nulle part"]'::jsonb, 0, '*noch nicht* signifie « pas encore ».', 7),
    ('a12e8644-22a3-5d60-a1a5-5627ae196251'::uuid, 'f7fce0dc-0358-5ab1-93a2-2c1ba919880c'::uuid, 'Après une négation, pour rectifier, on emploie…', 'mcq', '["sondern","aber","denn","oder"]'::jsonb, 0, '*Er ist nicht Deutscher, sondern Österreicher.* *aber* oppose sans rectifier.', 8),
    ('0312a77e-98c0-520b-8894-7fcc451f5d87'::uuid, '77627871-5522-5b4f-83d4-d02894a1009e'::uuid, 'Dans une subordonnée, le verbe conjugué se place…', 'mcq', '["À la fin de la subordonnée","En deuxième position","Juste après la conjonction","En première position"]'::jsonb, 0, '*Ich bleibe zu Hause, weil ich krank bin.*', 1),
    ('e0db2906-5f7c-5446-9662-8bcf63ef642a'::uuid, '77627871-5522-5b4f-83d4-d02894a1009e'::uuid, 'Dans « …, weil ich gearbeitet habe », quel mot ferme la phrase ?', 'mcq', '["L’auxiliaire conjugué habe","Le participe gearbeitet","Le sujet ich","La conjonction weil"]'::jsonb, 0, 'Le verbe CONJUGUÉ passe après le participe : c’est propre à la subordonnée.', 2),
    ('70516b4a-b02c-531a-97a1-626a23670be6'::uuid, '77627871-5522-5b4f-83d4-d02894a1009e'::uuid, '« denn » envoie le verbe à la fin, comme « weil ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*denn* est une conjonction de coordination : *Ich bleibe zu Hause, denn ich bin krank.*', 3),
    ('cd581e29-f26b-538b-a397-2944f0fc13c3'::uuid, '77627871-5522-5b4f-83d4-d02894a1009e'::uuid, 'Si la subordonnée ouvre la phrase, que se passe-t-il dans la principale ?', 'mcq', '["Le verbe suit immédiatement la virgule","Le sujet suit immédiatement la virgule","Rien ne change","La principale perd son verbe"]'::jsonb, 0, '*Weil ich krank bin, bleibe ich zu Hause.* La subordonnée occupe la première position.', 4),
    ('e5b4ea77-3493-513c-9a7e-c5a5b75349c2'::uuid, '77627871-5522-5b4f-83d4-d02894a1009e'::uuid, 'Quelle conjonction traduit « quand » pour un fait unique du passé ?', 'mcq', '["als","wenn","wann","ob"]'::jsonb, 0, '*Als ich zehn Jahre alt war…* — *wenn* vaut pour la répétition ou le présent.', 5),
    ('c20803f1-8d17-5002-bb0f-b46d0cfc0cea'::uuid, '77627871-5522-5b4f-83d4-d02894a1009e'::uuid, '« wann » peut introduire une subordonnée de temps ordinaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*wann* n’apparaît que dans une question, directe ou indirecte.', 6),
    ('87dfae7e-81f3-5f72-97a3-69aca0ded158'::uuid, '77627871-5522-5b4f-83d4-d02894a1009e'::uuid, 'Que signifie « obwohl » ?', 'mcq', '["Bien que","Parce que","Pour que","Depuis que"]'::jsonb, 0, '*Obwohl es regnet, gehe ich spazieren.*', 7),
    ('0b0bf3d7-ebb8-5aa2-b290-3aace53a0b45'::uuid, '77627871-5522-5b4f-83d4-d02894a1009e'::uuid, 'Quelle conjonction exprime le but ?', 'mcq', '["damit","weil","obwohl","nachdem"]'::jsonb, 0, '*Ich lerne, damit ich das Abitur bestehe.*', 8),
    ('e1d602d9-04cb-5c87-bbd9-7b219cbda3e0'::uuid, 'bd616e70-1a9f-569b-9bff-fb8f2bef033c'::uuid, 'Le pronom relatif prend son genre de l’antécédent et son cas…', 'mcq', '["De sa fonction dans la relative","De la fonction de l’antécédent","Du verbe de la principale","Il ne prend jamais de cas"]'::jsonb, 0, 'C’est le raisonnement en deux temps : genre avant, cas après.', 1),
    ('2a23967c-7301-59ac-a67c-07343c28ffb0'::uuid, 'bd616e70-1a9f-569b-9bff-fb8f2bef033c'::uuid, 'Comment traduire « l’homme que je vois » ?', 'mcq', '["Der Mann, den ich sehe","Der Mann, der ich sehe","Der Mann, dem ich sehe","Der Mann, dessen ich sehe"]'::jsonb, 0, 'Masculin + fonction de COD → accusatif *den*.', 2),
    ('b95c41f1-15db-5e24-8614-480584c71537'::uuid, 'bd616e70-1a9f-569b-9bff-fb8f2bef033c'::uuid, 'Quelle est la forme du relatif au datif pluriel ?', 'mcq', '["denen","den","deren","die"]'::jsonb, 0, '*Die Freunde, denen ich helfe.* C’est l’une des trois formes qui diffèrent de l’article.', 3),
    ('aa32d8ee-afc7-5fd5-90d1-5f8ffa244890'::uuid, 'bd616e70-1a9f-569b-9bff-fb8f2bef033c'::uuid, 'Dans une relative, le verbe conjugué reste en deuxième position.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La relative est une subordonnée : le verbe conjugué ferme la proposition.', 4),
    ('b893e0a9-bddb-540a-9264-e27a2d7124b0'::uuid, 'bd616e70-1a9f-569b-9bff-fb8f2bef033c'::uuid, 'Où se place la préposition dans une relative ?', 'mcq', '["Devant le pronom relatif","À la fin de la relative","Après le verbe","Elle disparaît"]'::jsonb, 0, '*Die Stadt, in der ich wohne.* Et c’est elle qui commande le cas.', 5),
    ('c957919d-48c9-5980-96bc-e861ca2735fb'::uuid, 'bd616e70-1a9f-569b-9bff-fb8f2bef033c'::uuid, 'Comment traduire « l’homme dont la voiture est en panne » ?', 'mcq', '["Der Mann, dessen Auto kaputt ist","Der Mann, deren Auto kaputt ist","Der Mann, den Auto kaputt ist","Der Mann, wessen Auto kaputt ist"]'::jsonb, 0, 'Génitif masculin *dessen*, et le nom qui suit n’a pas d’article.', 6),
    ('87770eed-8c66-5f52-8ca2-31ab27f1f50c'::uuid, 'bd616e70-1a9f-569b-9bff-fb8f2bef033c'::uuid, 'Après « alles », « nichts » ou « etwas », le relatif est…', 'mcq', '["was","das","wer","dessen"]'::jsonb, 0, '*Alles, was du sagst, ist richtig.*', 7),
    ('8595cce5-c236-535b-be0a-02dd12287770'::uuid, 'bd616e70-1a9f-569b-9bff-fb8f2bef033c'::uuid, '« deren » sert au génitif féminin et au génitif pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Die Frau, deren Sohn…* / *Die Leute, deren Kinder…*', 8),
    ('0cd3d874-b244-59d7-9b70-b442b60f0a76'::uuid, '714581be-3b83-58a5-b16b-7d2c38e179e7'::uuid, 'Avec quel auxiliaire se construit le passif d’action ?', 'mcq', '["werden","sein","haben","lassen"]'::jsonb, 0, '*Das Haus wird gebaut.* C’est *sein* qui donne le passif d’état.', 1),
    ('b4de2032-0c95-57e3-92f6-77d377a004d8'::uuid, '714581be-3b83-58a5-b16b-7d2c38e179e7'::uuid, 'Comment dit-on « la maison a été construite » ?', 'mcq', '["Das Haus ist gebaut worden","Das Haus ist gebaut geworden","Das Haus hat gebaut worden","Das Haus war gebaut"]'::jsonb, 0, 'Au parfait du passif, le participe de *werden* perd son *ge-* : *worden*.', 2),
    ('a3977d65-65d9-5ea0-a016-5fef71dcb2fe'::uuid, '714581be-3b83-58a5-b16b-7d2c38e179e7'::uuid, '« Das Haus ist gebaut » exprime…', 'mcq', '["Un résultat, un état","Une action en cours","Un futur","Une supposition"]'::jsonb, 0, 'C’est le passif d’état : la photo, pas le film.', 3),
    ('e692c6b3-d1c7-520f-86e1-39813d46b816'::uuid, '714581be-3b83-58a5-b16b-7d2c38e179e7'::uuid, 'Quel mot introduit l’agent quand c’est une personne ?', 'mcq', '["von + datif","durch + accusatif","mit + datif","für + accusatif"]'::jsonb, 0, '*Das Buch wurde von Goethe geschrieben.* *durch* introduit un moyen.', 4),
    ('bb535b33-a903-5a7a-a7aa-b9de896ac0c5'::uuid, '714581be-3b83-58a5-b16b-7d2c38e179e7'::uuid, 'L’allemand peut mettre au passif un verbe sans complément d’objet.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le passif impersonnel : *Hier wird getanzt.*', 5),
    ('bda32b83-4679-5ad4-9cc6-f5d788427311'::uuid, '714581be-3b83-58a5-b16b-7d2c38e179e7'::uuid, 'Comment traduire « le travail doit être fait aujourd’hui » ?', 'mcq', '["Die Arbeit muss heute gemacht werden","Die Arbeit muss heute gemacht worden","Die Arbeit wird heute machen müssen","Die Arbeit ist heute gemacht müssen"]'::jsonb, 0, 'Le modal se conjugue, le passif passe à l’infinitif en fin de phrase.', 6),
    ('6a825c8b-aaa6-53bc-ba6b-7694b6d0ccf5'::uuid, '714581be-3b83-58a5-b16b-7d2c38e179e7'::uuid, '« Er ist Arzt geworden » contient un passif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est *werden* employé seul, au sens de « devenir » — d’où *geworden* et non *worden*.', 7),
    ('b2f5a796-5443-510e-862a-293bc4902d8e'::uuid, '714581be-3b83-58a5-b16b-7d2c38e179e7'::uuid, 'Quelle tournure active remplace souvent le passif à l’oral ?', 'mcq', '["man + verbe actif","es gibt","sein + zu","lassen"]'::jsonb, 0, '*Man baut ein Haus* est plus courant que *Ein Haus wird gebaut.*', 8),
    ('b04baac6-9836-56a2-b576-10562f8f40c2'::uuid, '632031fc-a5a4-5119-87ec-3710908c2002'::uuid, 'Où se place « zu » avec un verbe à préverbe séparable ?', 'mcq', '["Entre le préverbe et le radical, en un seul mot","Devant le préverbe","Après l’infinitif","Il disparaît"]'::jsonb, 0, '*einzukaufen*, *aufzustehen*, *anzurufen*.', 1),
    ('5dbb233b-a16e-51ce-9169-f0c5e592c102'::uuid, '632031fc-a5a4-5119-87ec-3710908c2002'::uuid, 'Après un verbe de modalité, l’infinitif prend « zu ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Ich kann schwimmen.* Les modaux, *sehen*, *hören* et *lassen* refusent *zu*.', 2),
    ('ffcadcd3-ac8d-5d8e-b808-8fc1a60f9592'::uuid, '632031fc-a5a4-5119-87ec-3710908c2002'::uuid, 'Comment traduire « J’apprends l’allemand pour étudier à Berlin » ?', 'mcq', '["Ich lerne Deutsch, um in Berlin zu studieren","Ich lerne Deutsch, für in Berlin studieren","Ich lerne Deutsch zu studieren in Berlin","Ich lerne Deutsch, damit in Berlin zu studieren"]'::jsonb, 0, '*um… zu* exprime le but, avec virgule obligatoire.', 3),
    ('ff1f773a-67d5-5528-94f0-64590a2cb18c'::uuid, '632031fc-a5a4-5119-87ec-3710908c2002'::uuid, 'Quand faut-il employer « damit » plutôt que « um… zu » ?', 'mcq', '["Quand les deux propositions n’ont pas le même sujet","Quand la phrase est négative","Quand le verbe est séparable","Jamais"]'::jsonb, 0, '*Ich erkläre es, damit du es verstehst.*', 4),
    ('f8dc9c76-ff99-5e89-b8e4-bd80c21df4c3'::uuid, '632031fc-a5a4-5119-87ec-3710908c2002'::uuid, 'Que signifie « ohne etwas zu sagen » ?', 'mcq', '["Sans rien dire","Au lieu de parler","Pour ne rien dire","En disant quelque chose"]'::jsonb, 0, '*statt… zu* signifie « au lieu de ».', 5),
    ('3ccc6ea6-3f66-5ffd-bae4-19cafd698508'::uuid, '632031fc-a5a4-5119-87ec-3710908c2002'::uuid, '« Ich habe viel zu tun » signifie…', 'mcq', '["J’ai beaucoup à faire","Je dois être fait","Je fais beaucoup","J’aime beaucoup faire"]'::jsonb, 0, '*haben + zu* a une valeur active ; *sein + zu* une valeur passive.', 6),
    ('3a738eb2-a642-5cd9-9e34-1d1b6ff880e7'::uuid, '632031fc-a5a4-5119-87ec-3710908c2002'::uuid, '« Die Arbeit ist heute zu machen » a une valeur passive.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle équivaut à *Die Arbeit muss heute gemacht werden.*', 7),
    ('05d7a3af-6ef2-5ec6-89f8-d174b501102c'::uuid, '632031fc-a5a4-5119-87ec-3710908c2002'::uuid, 'Après « Ich gehe », le verbe suivant prend « zu ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les verbes de mouvement s’en passent : *Ich gehe schwimmen.*', 8),
    ('b2859af1-11a5-5fbb-b6f8-8cd1dd823145'::uuid, '18b9e596-ad03-59ee-aa46-4a3e23968004'::uuid, 'Quel est l’article défini neutre ?', 'mcq', '["das","der","die","den"]'::jsonb, 0, '*das Buch*, *das Haus*, *das Kind*.', 1),
    ('c55d10e7-e1cf-5bc4-a3d6-fa59093dfddd'::uuid, '18b9e596-ad03-59ee-aa46-4a3e23968004'::uuid, 'Au pluriel, l’article défini est « die » pour les trois genres.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*die Männer*, *die Frauen*, *die Kinder*.', 2),
    ('2a4a4384-ed6c-5dd9-9eb5-51b37350d735'::uuid, '18b9e596-ad03-59ee-aa46-4a3e23968004'::uuid, 'Quel est le genre de « Mädchen » ?', 'mcq', '["Neutre","Féminin","Masculin","Il n’en a pas"]'::jsonb, 0, 'Tous les diminutifs en *-chen* et *-lein* sont neutres, quel que soit le sens.', 3),
    ('53149a94-f28e-56f3-93e0-d8958711ba69'::uuid, '18b9e596-ad03-59ee-aa46-4a3e23968004'::uuid, 'Les noms en -ung sont généralement…', 'mcq', '["Féminins","Masculins","Neutres","Sans genre"]'::jsonb, 0, '*die Zeitung*, *die Wohnung*, *die Meinung*. Comme les noms en *-heit* et *-keit*.', 4),
    ('cb8e345c-4a2d-5a6f-b9e4-1bd51c38b458'::uuid, '18b9e596-ad03-59ee-aa46-4a3e23968004'::uuid, 'L’article indéfini « ein » possède un pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On dit simplement *Ich sehe Kinder*. Seule sa négation *kein* a un pluriel.', 5),
    ('39212ebb-9d28-5c6a-8dd3-71f917c18176'::uuid, '18b9e596-ad03-59ee-aa46-4a3e23968004'::uuid, 'À quel cas se met le sujet de la phrase ?', 'mcq', '["Au nominatif","À l’accusatif","Au datif","Au génitif"]'::jsonb, 0, 'C’est la forme du dictionnaire : *Der Hund schläft.*', 6),
    ('b9ffb2be-cdec-5286-8ce2-4ed01ff6d4c8'::uuid, '18b9e596-ad03-59ee-aa46-4a3e23968004'::uuid, 'Comment traduire « il est professeur » ?', 'mcq', '["Er ist Lehrer","Er ist ein Lehrer","Er ist der Lehrer","Er ist einen Lehrer"]'::jsonb, 0, 'Pas d’article devant un nom de métier après *sein* ou *werden*.', 7),
    ('78edb0ed-774e-587e-b8c6-958827aef101'::uuid, '18b9e596-ad03-59ee-aa46-4a3e23968004'::uuid, 'Dans « Das ist mein Buch », « das » est un article neutre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un démonstratif invariable qui signifie « ça » : il ne s’accorde à rien.', 8),
    ('54613569-4128-54c9-9b5e-404f050d3a0b'::uuid, '398a4f56-0ce8-5bf3-85b1-4e8a3f4dc021'::uuid, 'À quel cas se met le complément d’objet direct ?', 'mcq', '["À l’accusatif","Au datif","Au nominatif","Au génitif"]'::jsonb, 0, 'Le datif est celui du complément d’objet second.', 1),
    ('97014e99-65c2-5d71-bee5-14786c5e20ae'::uuid, '398a4f56-0ce8-5bf3-85b1-4e8a3f4dc021'::uuid, 'Que devient « der » au datif ?', 'mcq', '["dem","den","des","der"]'::jsonb, 0, '*mit dem Mann*. *den* est l’accusatif, *des* le génitif.', 2),
    ('d5b381fb-024d-5f01-8198-6a1a6200d2ab'::uuid, '398a4f56-0ce8-5bf3-85b1-4e8a3f4dc021'::uuid, 'Que devient « die » (féminin) au datif ?', 'mcq', '["der","dem","den","die"]'::jsonb, 0, 'Piège classique : *der* est à la fois le masculin nominatif et le féminin datif.', 3),
    ('558fa37b-ec8b-5e18-929c-c3d44928c949'::uuid, '398a4f56-0ce8-5bf3-85b1-4e8a3f4dc021'::uuid, 'Au datif pluriel, le nom prend un -n supplémentaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*mit den Kindern*, *aus den Ländern*.', 4),
    ('f543c59f-cf76-51ff-987d-4546e7bacf47'::uuid, '398a4f56-0ce8-5bf3-85b1-4e8a3f4dc021'::uuid, 'Les possessifs se déclinent comme…', 'mcq', '["ein et kein","l’article défini","les adjectifs forts","ils ne se déclinent pas"]'::jsonb, 0, 'D’où leur nom de « déterminants en ein- » : *meinen Bruder*, *meiner Schwester*.', 5),
    ('52ab138b-77f3-53de-9d4f-93cf5ea252fc'::uuid, '398a4f56-0ce8-5bf3-85b1-4e8a3f4dc021'::uuid, '« dieser » prend les terminaisons de l’article défini.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*diesen Mann*, *diesem Kind*, *dieser Frau*. Comme *jeder* et *welcher*.', 6),
    ('ea50291e-d9a9-5144-8058-98a80f475a71'::uuid, '398a4f56-0ce8-5bf3-85b1-4e8a3f4dc021'::uuid, 'Au génitif masculin, le nom prend…', 'mcq', '["-(e)s","-n","-er","rien du tout"]'::jsonb, 0, '*das Auto des Vaters*, *das Ende des Jahres*.', 7),
    ('e43c1061-a85e-5ccb-88aa-d4e1fb060c11'::uuid, '398a4f56-0ce8-5bf3-85b1-4e8a3f4dc021'::uuid, 'Quel genre change entre le nominatif et l’accusatif ?', 'mcq', '["Le masculin seul","Le féminin seul","Le neutre seul","Les trois genres"]'::jsonb, 0, '*der* → *den*, *ein* → *einen*. Féminin, neutre et pluriel ne bougent pas.', 8),
    ('e8d1ef45-f42b-52c4-80ed-8fb5138a6e5c'::uuid, 'b63d13c0-619c-5930-8a44-b67baf5b1d81'::uuid, 'Quel est le pronom accusatif de « er » ?', 'mcq', '["ihn","ihm","sie","es"]'::jsonb, 0, '*Ich sehe ihn.* *ihm* est le datif.', 1),
    ('5ab01a60-213c-51cc-9edb-646aa3fcf86f'::uuid, 'b63d13c0-619c-5930-8a44-b67baf5b1d81'::uuid, 'Comment reprendre « der Tisch » par un pronom ?', 'mcq', '["er","es","sie","ihn"]'::jsonb, 0, 'Le genre GRAMMATICAL commande : un objet masculin se reprend par *er*.', 2),
    ('4a5e1601-214e-5e97-915e-f3e73acab359'::uuid, 'b63d13c0-619c-5930-8a44-b67baf5b1d81'::uuid, 'Quel est le pronom datif de « sie » (elle) ?', 'mcq', '["ihr","ihn","ihnen","sie"]'::jsonb, 0, '*Ich helfe ihr.* Ne pas le confondre avec *ihr* = vous (2e personne du pluriel).', 3),
    ('59ece15e-c20d-5b39-b4fc-2d83f858e696'::uuid, 'b63d13c0-619c-5930-8a44-b67baf5b1d81'::uuid, 'Avec deux pronoms compléments, l’ordre est…', 'mcq', '["Accusatif puis datif","Datif puis accusatif","Indifférent","Toujours alphabétique"]'::jsonb, 0, '*Ich gebe es dir* — l’inverse de l’ordre des groupes nominaux.', 4),
    ('4793bc04-36e5-58ce-8434-a62bf34548e8'::uuid, 'b63d13c0-619c-5930-8a44-b67baf5b1d81'::uuid, '« Sie » de politesse se conjugue comme la 3e personne du pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Können Sie mir helfen?* Et il garde toujours sa majuscule.', 5),
    ('41cf4ce5-c720-57bc-911b-d90e40fa5309'::uuid, 'b63d13c0-619c-5930-8a44-b67baf5b1d81'::uuid, 'Dans « Es regnet », « es » est…', 'mcq', '["Un sujet apparent","Un COD","Un possessif","Une faute"]'::jsonb, 0, 'Comme dans *Es gibt* : un sujet grammatical vide.', 6),
    ('834a1c5d-69eb-5fc3-ad72-336f25bf7719'::uuid, 'b63d13c0-619c-5930-8a44-b67baf5b1d81'::uuid, '« man » se décline « einen » à l’accusatif et « einem » au datif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Das macht einen müde.* C’est un pronom indéfini, pas un pronom personnel.', 7),
    ('1875063e-025a-5a5f-b60d-673a411bddad'::uuid, 'b63d13c0-619c-5930-8a44-b67baf5b1d81'::uuid, 'Où remontent les pronoms compléments dans la phrase ?', 'mcq', '["Juste après le verbe conjugué","À la fin de la phrase","Avant le verbe conjugué","Après le participe passé"]'::jsonb, 0, '*Gestern hat mich mein Vater angerufen* : ils peuvent même précéder le sujet nominal.', 8),
    ('6dbfe31c-8799-518c-bb1a-8cf628267272'::uuid, '46d4c2a0-8c09-56e7-840b-b224b3e46d63'::uuid, '« dieser » se décline comme…', 'mcq', '["L’article défini","L’article indéfini","Un adjectif fort","Il ne se décline pas"]'::jsonb, 0, '*diesen Mann*, *diesem Kind*, *dieser Frau*.', 1),
    ('bf58dea6-b9d0-5285-b4e9-a6c94d641a9c'::uuid, '46d4c2a0-8c09-56e7-840b-b224b3e46d63'::uuid, 'Dans « Den kenne ich gut! », « den » est…', 'mcq', '["Un démonstratif accentué","Un article défini","Un pronom relatif","Une préposition"]'::jsonb, 0, 'C’est la forme démonstrative la plus courante à l’oral.', 2),
    ('a00f2c28-d60b-53ed-8451-8296e593aba4'::uuid, '46d4c2a0-8c09-56e7-840b-b224b3e46d63'::uuid, 'Quelle est la forme du démonstratif au datif pluriel ?', 'mcq', '["denen","den","dessen","deren"]'::jsonb, 0, 'Comme le pronom relatif : *denen* et non *den*.', 3),
    ('e879e846-dc78-532d-9e9b-d6e21e5dac8b'::uuid, '46d4c2a0-8c09-56e7-840b-b224b3e46d63'::uuid, '« Ich traf Paul und dessen Bruder » signifie…', 'mcq', '["Le frère de Paul","Mon frère","Le frère de quelqu’un d’autre","Le même frère"]'::jsonb, 0, '*dessen* lève l’ambiguïté que *seinen* laisserait planer.', 4),
    ('dfed2b31-6b75-5dd2-8c5b-884545e95d69'::uuid, '46d4c2a0-8c09-56e7-840b-b224b3e46d63'::uuid, '« derselbe » se décline sur ses deux morceaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*in demselben Haus* : *der-* comme l’article, *-selbe* comme un adjectif faible.', 5),
    ('df36d904-fe5e-587d-8a35-111a81a6cc40'::uuid, '46d4c2a0-8c09-56e7-840b-b224b3e46d63'::uuid, 'Comment traduire « Ce sont mes parents » ?', 'mcq', '["Das sind meine Eltern","Die sind meine Eltern","Das ist meine Eltern","Diese sind meine Eltern"]'::jsonb, 0, '*das* reste invariable ; le verbe s’accorde avec ce qui suit.', 6),
    ('a8058d9a-40fa-5611-805e-dcb285a1572b'::uuid, '46d4c2a0-8c09-56e7-840b-b224b3e46d63'::uuid, '« dass » et « das » s’emploient indifféremment.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*dass* est la conjonction « que » ; *das* l’article ou le démonstratif. Test : remplacer par *dieses*.', 7),
    ('591b5272-f1aa-55be-ae69-5fc05b6cfe6f'::uuid, '46d4c2a0-8c09-56e7-840b-b224b3e46d63'::uuid, '« jener » appartient surtout…', 'mcq', '["À la langue écrite et soutenue","À l’oral familier","Au vocabulaire technique","Au vieil allemand disparu"]'::jsonb, 0, 'À l’oral, on lui préfère *dieser… der da*.', 8),
    ('4fbeff7c-495e-58da-ab75-212217c324bf'::uuid, '90c66fce-aa72-5529-9be6-b360bd034afc'::uuid, 'Quel est le pluriel de « das Buch » ?', 'mcq', '["die Bücher","die Buche","die Buchs","die Buchen"]'::jsonb, 0, 'Pluriel en *-er* avec inflexion, typique des neutres.', 1),
    ('00d4e9c2-04d1-504f-a554-df4a030404c0'::uuid, '90c66fce-aa72-5529-9be6-b360bd034afc'::uuid, 'La quasi-totalité des féminins font leur pluriel en…', 'mcq', '["-(e)n","-e","-er","-s"]'::jsonb, 0, '*die Frauen*, *die Blumen*, *die Zeitungen* — et jamais d’inflexion.', 2),
    ('3e0b80df-8cb4-5482-8ad2-2fa21def2696'::uuid, '90c66fce-aa72-5529-9be6-b360bd034afc'::uuid, '« der Lehrer » a le même mot au singulier et au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les masculins en *-er*, *-el*, *-en* ne changent pas : seul l’article le dit.', 3),
    ('297b5d88-ee77-5f3f-baba-a14886d2ebda'::uuid, '90c66fce-aa72-5529-9be6-b360bd034afc'::uuid, 'Quel est le pluriel de « das Auto » ?', 'mcq', '["die Autos","die Auten","die Autoer","die Aute"]'::jsonb, 0, 'Les emprunts font leur pluriel en *-s*.', 4),
    ('860647d6-6ed3-5fda-bc68-f091593ebc63'::uuid, '90c66fce-aa72-5529-9be6-b360bd034afc'::uuid, 'Au datif pluriel, que prend le nom ?', 'mcq', '["Un -n s’il n’en a pas déjà un","Un -s","Un -er","Rien"]'::jsonb, 0, '*mit den Kindern*, *aus den Städten* — sauf les pluriels en *-s*.', 5),
    ('85770fb5-4e2d-5d48-a3f5-d10a1e1456fb'::uuid, '90c66fce-aa72-5529-9be6-b360bd034afc'::uuid, 'Quel est le pluriel de « die Lehrerin » ?', 'mcq', '["die Lehrerinnen","die Lehrerins","die Lehrerine","die Lehrerinen"]'::jsonb, 0, 'Les noms en *-in* doublent le n avant *-en*.', 6),
    ('b43554fa-583b-5755-9ccd-7e4af5b898ca'::uuid, '90c66fce-aa72-5529-9be6-b360bd034afc'::uuid, '« die Leute » n’existe qu’au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *die Polizei* ou *die Milch* n’existent qu’au singulier.', 7),
    ('af248cc4-577e-5180-a1c6-acf8ef6a27c6'::uuid, '90c66fce-aa72-5529-9be6-b360bd034afc'::uuid, 'Au pluriel, l’article défini dépend du genre du nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est *die* pour les trois genres au nominatif et à l’accusatif.', 8),
    ('09ebdda9-5e73-5f13-8dce-91ef905ae206'::uuid, 'a3b038a8-1f52-5e56-b38f-661d07e1b8f5'::uuid, 'Après « sein », l’adjectif attribut…', 'mcq', '["Reste invariable","S’accorde en genre","S’accorde en nombre","Prend toujours -e"]'::jsonb, 0, '*Der Mann ist alt*, *die Frau ist alt*, *die Kinder sind alt*.', 1),
    ('cecbecc1-0f92-5325-9cac-d3c2c9c6a010'::uuid, 'a3b038a8-1f52-5e56-b38f-661d07e1b8f5'::uuid, '« Die Frau ist alte » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’attribut ne prend aucune terminaison : *Die Frau ist alt.*', 2),
    ('69e47ea9-5b37-5e9c-bc2a-fbc06c388038'::uuid, 'a3b038a8-1f52-5e56-b38f-661d07e1b8f5'::uuid, 'Quel verbe n’appelle PAS un attribut invariable ?', 'mcq', '["sehen","sein","werden","bleiben"]'::jsonb, 0, '*sein*, *werden* et *bleiben* sont les trois verbes de base de l’attribut.', 3),
    ('8daa3d6d-7e1b-53de-9e78-d789d88ca597'::uuid, 'a3b038a8-1f52-5e56-b38f-661d07e1b8f5'::uuid, 'Comment traduire « une vieille femme » ?', 'mcq', '["eine alte Frau","eine alt Frau","ein alte Frau","eine alten Frau"]'::jsonb, 0, 'Devant le nom, l’adjectif est épithète : il se décline.', 4),
    ('e4af6816-e838-5089-9153-0520fb5cb9ce'::uuid, 'a3b038a8-1f52-5e56-b38f-661d07e1b8f5'::uuid, 'En allemand, l’adverbe se forme avec une terminaison spéciale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le même mot sert d’adjectif et d’adverbe : *Er singt schön.*', 5),
    ('133fb10e-4761-5689-93e0-253478194a02'::uuid, 'a3b038a8-1f52-5e56-b38f-661d07e1b8f5'::uuid, 'Dans « Der Zug ist schneller », la terminaison -er marque…', 'mcq', '["Le comparatif","Le masculin","Le pluriel","Le datif"]'::jsonb, 0, 'Ce n’est pas un accord : l’attribut ne s’accorde jamais.', 6),
    ('faa1d6e0-cb84-5d84-9816-015bfc282b89'::uuid, 'a3b038a8-1f52-5e56-b38f-661d07e1b8f5'::uuid, 'Comment traduire « je trouve le livre intéressant » ?', 'mcq', '["Ich finde das Buch interessant","Ich finde das Buch interessantes","Ich finde das interessante Buch","Ich finde interessant das Buch"]'::jsonb, 0, '*finden* + COD + attribut invariable.', 7),
    ('283ca64b-4284-508c-96ea-d72cb5874a51'::uuid, 'a3b038a8-1f52-5e56-b38f-661d07e1b8f5'::uuid, 'La différence entre attribut et épithète tient à la place de l’adjectif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après le verbe : invariable. Devant le nom : décliné.', 8),
    ('3df41f22-b7ba-59be-9166-b3ea352f029a'::uuid, '9a3a1905-e380-5abc-8d39-d91e92e4acb8'::uuid, 'Quand l’adjectif prend-il la déclinaison forte ?', 'mcq', '["Quand aucun déterminant ne porte la marque du cas","Après l’article défini","Après ein et kein","Jamais au pluriel"]'::jsonb, 0, '*kalter Kaffee*, *frische Milch* : l’adjectif prend les terminaisons de l’article défini.', 1),
    ('9fc2dc7d-4689-594e-9f08-127b3de45bbb'::uuid, '9a3a1905-e380-5abc-8d39-d91e92e4acb8'::uuid, 'Comment traduire « un vieil homme » (nominatif) ?', 'mcq', '["ein alter Mann","ein alt Mann","ein alten Mann","ein alte Mann"]'::jsonb, 0, '*ein* ne marque pas le masculin nominatif : l’adjectif le fait à sa place.', 2),
    ('6d6acd44-1c5d-5117-a402-0be99d2d2f2f'::uuid, '9a3a1905-e380-5abc-8d39-d91e92e4acb8'::uuid, 'Après « der », l’adjectif prend seulement -e ou -en.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la déclinaison faible : *der alte Mann*, *dem alten Mann*.', 3),
    ('4716bc20-9d45-5096-a049-e42b2734b586'::uuid, '9a3a1905-e380-5abc-8d39-d91e92e4acb8'::uuid, 'Comment dit-on « une vieille maison » à l’accusatif (das Haus) ?', 'mcq', '["ein altes Haus","ein alten Haus","eine alte Haus","ein alte Haus"]'::jsonb, 0, 'Neutre accusatif : *ein* ne marque rien, l’adjectif prend *-es*.', 4),
    ('ac52e28c-3890-5c62-b839-9dfc153d22fa'::uuid, '9a3a1905-e380-5abc-8d39-d91e92e4acb8'::uuid, 'Après « meinem », l’adjectif prend…', 'mcq', '["-en","-er","-es","-e"]'::jsonb, 0, 'Le possessif marque déjà le datif : *meinem alten Freund*.', 5),
    ('e9c32589-3093-5b24-b731-fc5df1073518'::uuid, '9a3a1905-e380-5abc-8d39-d91e92e4acb8'::uuid, '« hoch » garde son c devant une terminaison.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*ein hoher Berg*, *das hohe Haus* : le *c* disparaît.', 6),
    ('1c26680d-c4e5-5ff9-86c7-f80dc6a44d3f'::uuid, '9a3a1905-e380-5abc-8d39-d91e92e4acb8'::uuid, 'Que devient « teuer » dans « ein … Auto » ?', 'mcq', '["teures","teueres","teuers","teuer"]'::jsonb, 0, '*teuer* et *dunkel* perdent leur *e* : *ein teures Auto*, *ein dunkles Zimmer*.', 7),
    ('2cf1af25-fa36-5db2-bb2a-b69a8dafa761'::uuid, '9a3a1905-e380-5abc-8d39-d91e92e4acb8'::uuid, '« rosa » et « lila » se déclinent comme les autres adjectifs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les adjectifs en *-a* sont invariables : *ein rosa Kleid*.', 8),
    ('e2f10f7b-b0d6-58a5-a5fa-2a62bcf147ed'::uuid, 'd202dead-505d-5bfc-acc1-61b0faacd912'::uuid, 'Comment traduire « Anna et son frère » ?', 'mcq', '["Anna und ihr Bruder","Anna und sein Bruder","Anna und seinen Bruder","Anna und ihre Bruder"]'::jsonb, 0, 'Le radical suit le POSSESSEUR (Anna → *ihr-*), la terminaison l’objet possédé (*Bruder*, masculin).', 1),
    ('91fcf5ac-35a3-504a-8dd9-401365c35a60'::uuid, 'd202dead-505d-5bfc-acc1-61b0faacd912'::uuid, 'Comment traduire « Peter et sa sœur » ?', 'mcq', '["Peter und seine Schwester","Peter und ihre Schwester","Peter und sein Schwester","Peter und ihren Schwester"]'::jsonb, 0, 'Radical *sein-* (Peter), terminaison féminine (*Schwester*).', 2),
    ('c4cd1e72-1de1-5e3f-ab2d-1cbc677643b2'::uuid, 'd202dead-505d-5bfc-acc1-61b0faacd912'::uuid, 'Le possessif se décline comme…', 'mcq', '["ein et kein","l’article défini","un adjectif faible","il ne se décline pas"]'::jsonb, 0, 'Avec en plus un pluriel : *meine Freunde*, *meinen Freunden*.', 3),
    ('ecf13c71-6109-5b7b-b24f-dc1af602c976'::uuid, 'd202dead-505d-5bfc-acc1-61b0faacd912'::uuid, 'Que devient « euer » devant une terminaison ?', 'mcq', '["eur-","euer-","eue-","eur-e-"]'::jsonb, 0, '*eure Mutter*, *euren Vater*. *unser*, lui, garde son *e*.', 4),
    ('eafc23d2-e717-5e3a-8bb1-8d1905f1d80a'::uuid, 'd202dead-505d-5bfc-acc1-61b0faacd912'::uuid, '« Ihr » avec majuscule signifie « leur ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec majuscule, c’est le possessif de politesse : « votre ».', 5),
    ('56ceb535-8384-545e-930f-ebbd3228e75d'::uuid, 'd202dead-505d-5bfc-acc1-61b0faacd912'::uuid, 'Comment dit-on « je me lave les mains » ?', 'mcq', '["Ich wasche mir die Hände","Ich wasche meine Hände mir","Ich wasche mich die Hände","Ich wasche meinen Händen"]'::jsonb, 0, 'Avec les parties du corps, l’allemand préfère article + datif au possessif.', 6),
    ('5f4a405b-013a-5767-99ac-03e6b8f5034e'::uuid, 'd202dead-505d-5bfc-acc1-61b0faacd912'::uuid, 'Employé seul, « mein » prend les terminaisons de l’article défini.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Das ist meins*, *Das ist meiner* : il devient pronom possessif.', 7),
    ('4d5b68f2-ee50-5d5d-9180-e19805ac5f66'::uuid, 'd202dead-505d-5bfc-acc1-61b0faacd912'::uuid, 'Dans « Das Kind und seine Mutter », pourquoi « seine » ?', 'mcq', '["Parce que « Kind » est neutre, donc radical sein-","Parce que « Mutter » est féminin","Parce que l’enfant est un garçon","Parce que c’est une exception"]'::jsonb, 0, 'Le radical suit le genre GRAMMATICAL du possesseur, pas son sexe.', 8),
    ('35ccbc6c-c558-50e0-8be0-fca03dcb377e'::uuid, '961080c8-c1ff-563f-b68f-7844c76d975b'::uuid, 'Comment dit-on « la voiture de Peter » ?', 'mcq', '["Peters Auto","Peter’s Auto","das Auto Peters","der Peter Auto"]'::jsonb, 0, 'Le nom propre passe devant, avec un *-s* sans apostrophe.', 1),
    ('4728f5d3-7a49-5ba8-a354-83d6cb8dfe65'::uuid, '961080c8-c1ff-563f-b68f-7844c76d975b'::uuid, 'Comment dit-on « la voiture du père » ?', 'mcq', '["das Auto des Vaters","das Auto der Vater","des Vaters das Auto","das Auto dem Vater"]'::jsonb, 0, 'Génitif masculin : *des* + nom en *-(e)s*, placé derrière.', 2),
    ('fbd6d087-7bde-5fc3-aa84-2c7f94fce67e'::uuid, '961080c8-c1ff-563f-b68f-7844c76d975b'::uuid, 'Au génitif féminin, le nom prend un -s.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seuls les masculins et les neutres le prennent : *das Haus der Frau*.', 3),
    ('d3af163b-bcdc-5f06-be23-d17a78c1ab99'::uuid, '961080c8-c1ff-563f-b68f-7844c76d975b'::uuid, 'Quelle question introduit le génitif ?', 'mcq', '["Wessen?","Wem?","Wen?","Wo?"]'::jsonb, 0, '*Wessen Buch ist das?*', 4),
    ('2c61cfaf-3a90-51de-b595-b73d088cd26b'::uuid, '961080c8-c1ff-563f-b68f-7844c76d975b'::uuid, 'Quelle préposition régit le génitif ?', 'mcq', '["während","mit","für","bei"]'::jsonb, 0, 'Comme *wegen*, *trotz*, *statt*, *innerhalb* : *während des Sommers*.', 5),
    ('88196b00-8a20-5653-af82-dc528b53ad10'::uuid, '961080c8-c1ff-563f-b68f-7844c76d975b'::uuid, '« ein Freund von mir » est une tournure correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*von* + datif remplace le génitif, surtout à l’oral.', 6),
    ('a9853d82-a14b-5f41-9420-2b072364ca03'::uuid, '961080c8-c1ff-563f-b68f-7844c76d975b'::uuid, 'Le génitif saxon s’écrit avec une apostrophe, comme en anglais.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Annas Buch*, sans apostrophe — sauf après un son sifflant : *Thomas’ Auto*.', 7),
    ('edb3440e-24e7-54bc-a796-cfb4481a4285'::uuid, '961080c8-c1ff-563f-b68f-7844c76d975b'::uuid, 'Au génitif pluriel, l’article est…', 'mcq', '["der","des","den","die"]'::jsonb, 0, '*die Bücher der Kinder*, sans marque supplémentaire sur le nom.', 8),
    ('87661c72-bab2-5f34-8fbe-6e3b519a5361'::uuid, '7d2bae92-f09b-5876-9ac0-227abc56568c'::uuid, 'Comment forme-t-on le comparatif d’un adjectif long comme « interessant » ?', 'mcq', '["interessanter","mehr interessant","am interessanten","interessant als"]'::jsonb, 0, 'Quelle que soit la longueur du mot, c’est la terminaison *-er*.', 1),
    ('352b39d9-e86e-5d6a-b6b0-98d449521b1a'::uuid, '7d2bae92-f09b-5876-9ac0-227abc56568c'::uuid, 'Quel mot introduit le second terme d’une comparaison d’inégalité ?', 'mcq', '["als","wie","wenn","denn"]'::jsonb, 0, '*Peter ist größer als Paul.* *wie* sert à l’égalité.', 2),
    ('46d62665-fa33-5730-b9a4-83c145e92da2'::uuid, '7d2bae92-f09b-5876-9ac0-227abc56568c'::uuid, 'Comment dit-on « aussi grand que » ?', 'mcq', '["so groß wie","so groß als","größer wie","als groß wie"]'::jsonb, 0, '*so… wie* pour l’égalité, *…-er als* pour l’inégalité.', 3),
    ('29c9d8d7-0ad1-5c36-a964-81d03d995271'::uuid, '7d2bae92-f09b-5876-9ac0-227abc56568c'::uuid, 'Quel est le comparatif de « gut » ?', 'mcq', '["besser","guter","mehr gut","gutter"]'::jsonb, 0, 'Irrégulier, comme *viel → mehr* et *gern → lieber*.', 4),
    ('cd73d45f-76be-567d-beb5-d55da9269304'::uuid, '7d2bae92-f09b-5876-9ac0-227abc56568c'::uuid, '« Ich trinke lieber Tee » signifie…', 'mcq', '["Je préfère le thé","Je bois beaucoup de thé","Je bois le meilleur thé","J’aimerais du thé"]'::jsonb, 0, '*lieber* est le comparatif de *gern* : c’est ainsi qu’on exprime la préférence.', 5),
    ('19cb3e9d-2eb4-5eb7-b9f7-50ce1c91daa3'::uuid, '7d2bae92-f09b-5876-9ac0-227abc56568c'::uuid, 'Devant un nom, le comparatif ne se décline pas.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*ein größeres Haus*, *mein älterer Bruder* : deux terminaisons se suivent.', 6),
    ('fc96b3fc-26d5-5b20-9f01-37da34051892'::uuid, '7d2bae92-f09b-5876-9ac0-227abc56568c'::uuid, 'Comment dit-on « de plus en plus froid » ?', 'mcq', '["immer kälter","mehr und mehr kalt","so kalt wie","am kältesten"]'::jsonb, 0, '*Es wird immer kälter.* Et *je… desto* pour « plus… plus ».', 7),
    ('91ebcd56-ce12-5793-bf20-32abad9237e7'::uuid, '7d2bae92-f09b-5876-9ac0-227abc56568c'::uuid, '« mehr groß » est une façon correcte de dire « plus grand ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*mehr* traduit « plus » de quantité ; le comparatif d’un adjectif se fait en *-er*.', 8),
    ('1f430d45-43c3-5a1b-bfac-3cd7aa87cff9'::uuid, '78af3bfd-32c3-5fdd-9537-786513c895c7'::uuid, 'Quelle forme du superlatif s’emploie après « sein » ?', 'mcq', '["am + -sten","der + -ste","mehr + adjectif","so + adjectif"]'::jsonb, 0, '*Der Zug ist am schnellsten.* La forme en *der/die/das* est réservée à l’épithète.', 1),
    ('1193f441-9bde-53a8-a09c-946be76a07c7'::uuid, '78af3bfd-32c3-5fdd-9537-786513c895c7'::uuid, 'Comment dit-on « le train le plus rapide » ?', 'mcq', '["der schnellste Zug","der Zug am schnellsten","am schnellsten Zug","der schneller Zug"]'::jsonb, 0, 'Épithète : article défini + adjectif au superlatif décliné.', 2),
    ('ddb890ef-a066-5421-8ce5-43f5b7d06154'::uuid, '78af3bfd-32c3-5fdd-9537-786513c895c7'::uuid, 'Pourquoi dit-on « am ältesten » et non « am altsten » ?', 'mcq', '["On intercale un e après d, t, s, ß, z","C’est une exception unique","Le e marque le datif","Pour éviter l’Umlaut"]'::jsonb, 0, 'Un *e* de liaison rend la forme prononçable.', 3),
    ('12c53c56-4bdb-5033-ab9b-e6396fcf9743'::uuid, '78af3bfd-32c3-5fdd-9537-786513c895c7'::uuid, 'Quel est le superlatif de « gut » ?', 'mcq', '["am besten","am gutsten","am mehrsten","am guten"]'::jsonb, 0, 'Série irrégulière : *gut → besser → am besten*.', 4),
    ('26eeb3fb-6dac-50bc-a3fb-3d4896adc971'::uuid, '78af3bfd-32c3-5fdd-9537-786513c895c7'::uuid, '« am liebsten » signifie…', 'mcq', '["Ce que je préfère par-dessus tout","Le plus aimé de tous","Avec amour","Aussi volontiers que"]'::jsonb, 0, '*Am liebsten lese ich Krimis* — une tournure très utile pour donner son avis.', 5),
    ('a2338aa4-7e5c-5512-a2b4-4b0c2eb24850'::uuid, '78af3bfd-32c3-5fdd-9537-786513c895c7'::uuid, 'La forme « am schnellsten » se décline devant un nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est figée ; devant un nom, on passe à *der schnellste*.', 6),
    ('05295683-012d-52a5-b536-7eb1cd0f0ff8'::uuid, '78af3bfd-32c3-5fdd-9537-786513c895c7'::uuid, 'Quel est le superlatif de « hoch » ?', 'mcq', '["am höchsten","am hochsten","am höhesten","am hohesten"]'::jsonb, 0, 'Comme *nah → am nächsten* : à apprendre par cœur.', 7),
    ('93de20c7-f292-5643-a588-95906f899d35'::uuid, '78af3bfd-32c3-5fdd-9537-786513c895c7'::uuid, 'Comment introduire le complément d’un superlatif ?', 'mcq', '["von ou unter + datif","als + nominatif","wie + accusatif","für + accusatif"]'::jsonb, 0, '*Er ist der Größte von allen* / *unter seinen Freunden*.', 8),
    ('df33906d-4719-508e-8895-f15e12002f42'::uuid, 'faf0e499-88c9-5851-a4eb-d3dc72420718'::uuid, 'Quelles prépositions régissent toujours l’accusatif ?', 'mcq', '["durch, für, gegen, ohne, um","aus, bei, mit, nach, von","an, auf, in, über, unter","wegen, trotz, während"]'::jsonb, 0, 'Une liste à apprendre en bloc : elle ne dépend jamais du sens.', 1),
    ('e1e02e0c-0ce9-5ac9-8314-55209a6a079b'::uuid, 'faf0e499-88c9-5851-a4eb-d3dc72420718'::uuid, 'Comment traduire « pour mon frère » ?', 'mcq', '["für meinen Bruder","für meinem Bruder","für mein Bruder","für meines Bruders"]'::jsonb, 0, '*für* + accusatif : le masculin devient *meinen*.', 2),
    ('51e9b4bf-e05c-57e0-9dbc-a85b5b5d7898'::uuid, 'faf0e499-88c9-5851-a4eb-d3dc72420718'::uuid, '« gegen acht Uhr » signifie…', 'mcq', '["Vers huit heures","À huit heures précises","Avant huit heures","Contre huit heures"]'::jsonb, 0, 'Pour l’heure précise, c’est *um acht Uhr*.', 3),
    ('b8c43c20-2ff4-535d-8be3-4a21ce342eec'::uuid, 'faf0e499-88c9-5851-a4eb-d3dc72420718'::uuid, 'Où se place « entlang » ?', 'mcq', '["Après le nom","Avant le nom","En fin de phrase","Devant le verbe"]'::jsonb, 0, '*die Straße entlang* : c’est la seule de la liste à se postposer.', 4),
    ('451729e0-a1d8-578f-bdeb-229f84ec108b'::uuid, 'faf0e499-88c9-5851-a4eb-d3dc72420718'::uuid, '« für das » se contracte en « fürs ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *durch das → durchs* et *um das → ums*.', 5),
    ('57baa2ec-1d2f-585f-b184-ea6f1e7ff11e'::uuid, 'faf0e499-88c9-5851-a4eb-d3dc72420718'::uuid, 'Comment traduire « sans argent » ?', 'mcq', '["ohne Geld","ohne dem Geld","ohne das Geld haben","ohne Geldes"]'::jsonb, 0, '*ohne* se passe le plus souvent d’article.', 6),
    ('a1a22df0-ed1d-5190-9484-2ad32e29d73a'::uuid, 'faf0e499-88c9-5851-a4eb-d3dc72420718'::uuid, 'Comment traduire « pour apprendre » ?', 'mcq', '["um zu lernen","für lernen","für zu lernen","um lernen"]'::jsonb, 0, '*für* introduit un groupe nominal, jamais un verbe : le but se dit *um… zu*.', 7),
    ('f8fc0822-83a8-5341-9b0b-cb49bd44a6b6'::uuid, 'faf0e499-88c9-5851-a4eb-d3dc72420718'::uuid, '« bis » est souvent suivi d’une seconde préposition.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*bis zum Bahnhof*, *bis zur Brücke* — et c’est alors elle qui commande le cas.', 8),
    ('c2d96c58-f9af-50ba-b53f-11b66baea341'::uuid, '24da36a6-025e-566a-a983-9588143da21f'::uuid, 'Quelle série de prépositions régit le datif ?', 'mcq', '["aus, bei, mit, nach, seit, von, zu","durch, für, gegen, ohne, um","wegen, trotz, während, statt","an, auf, hinter, in, neben"]'::jsonb, 0, 'La formule *aus-bei-mit-nach-seit-von-zu* se retient d’un bloc.', 1),
    ('438c8f3f-6d23-5278-a6cf-e799f3939ce7'::uuid, '24da36a6-025e-566a-a983-9588143da21f'::uuid, '« Ich komme aus der Schweiz » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*aus* impose le datif : *die Schweiz* devient *der Schweiz*.', 2),
    ('97f1aa01-ddfe-5fe6-805f-501c300d80bb'::uuid, '24da36a6-025e-566a-a983-9588143da21f'::uuid, 'En quoi se contracte « zu der » ?', 'mcq', '["zur","zum","zud","zurd"]'::jsonb, 0, '*zur Schule*, *zur Post*. Et *zu dem → zum*.', 3),
    ('a3ffde01-e19f-5eeb-96c0-82f34e258638'::uuid, '24da36a6-025e-566a-a983-9588143da21f'::uuid, 'Comment dit-on « je vais chez le médecin » ?', 'mcq', '["Ich gehe zum Arzt","Ich gehe nach dem Arzt","Ich gehe bei dem Arzt","Ich gehe in den Arzt"]'::jsonb, 0, '*zu* + personne vue comme un but ; *bei* dirait où l’on se trouve déjà.', 4),
    ('77da60d2-fddf-57eb-b13d-24617a0f4bec'::uuid, '24da36a6-025e-566a-a983-9588143da21f'::uuid, 'Avec « seit », quel temps emploie-t-on en allemand ?', 'mcq', '["Le présent","Le parfait","Le prétérit","Le futur"]'::jsonb, 0, '*Ich lerne seit drei Jahren Deutsch.*', 5),
    ('72a8ee0f-2928-5d9c-b6a9-98b6b8d1159e'::uuid, '24da36a6-025e-566a-a983-9588143da21f'::uuid, 'Comment dit-on « je vais en Suisse » ?', 'mcq', '["Ich fahre in die Schweiz","Ich fahre nach die Schweiz","Ich fahre nach der Schweiz","Ich fahre zu Schweiz"]'::jsonb, 0, 'Les pays qui ont un article prennent *in* + accusatif ; les autres, *nach*.', 6),
    ('06650b8e-23f7-599b-9936-ab9514c703f7'::uuid, '24da36a6-025e-566a-a983-9588143da21f'::uuid, '« nach Hause » et « zu Hause » signifient la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*nach Hause* = vers la maison (mouvement), *zu Hause* = à la maison (sans mouvement).', 7),
    ('57a39b16-d4c9-5cff-bb00-4bcec8cb34fe'::uuid, '24da36a6-025e-566a-a983-9588143da21f'::uuid, 'Que signifie « bei » dans « beim Essen » ?', 'mcq', '["Pendant, lors de","Après","Sans","Contre"]'::jsonb, 0, '*bei* couvre aussi le moment d’une action en cours.', 8),
    ('3c4a3aa2-d348-5b0e-b52a-a0b45bdb2300'::uuid, '40b9ec35-d46d-57f8-bc72-9ed608b5dfd1'::uuid, 'Quel cas suit une préposition mixte en cas de déplacement ?', 'mcq', '["L’accusatif","Le datif","Le génitif","Le nominatif"]'::jsonb, 0, 'Question *wohin?* → accusatif. Question *wo?* → datif.', 1),
    ('c8321e5d-7dc2-5979-82da-e1d70571b4f7'::uuid, '40b9ec35-d46d-57f8-bc72-9ed608b5dfd1'::uuid, '« Ich bin in der Schule » exprime…', 'mcq', '["Une localisation","Un déplacement","Une possession","Une cause"]'::jsonb, 0, 'Question *wo?* → datif.', 2),
    ('4b7baac8-bfad-5a6f-9318-0b55b43d6ea2'::uuid, '40b9ec35-d46d-57f8-bc72-9ed608b5dfd1'::uuid, 'Combien y a-t-il de prépositions mixtes ?', 'mcq', '["Neuf","Cinq","Sept","Douze"]'::jsonb, 0, '*an, auf, hinter, in, neben, über, unter, vor, zwischen*.', 3),
    ('9b47eebb-58f1-5d6c-95f8-5c611a7646c8'::uuid, '40b9ec35-d46d-57f8-bc72-9ed608b5dfd1'::uuid, 'Quel verbe demande le datif : « stehen » ou « stellen » ?', 'mcq', '["stehen","stellen","Les deux","Aucun des deux"]'::jsonb, 0, '*stehen* décrit un état (datif) ; *stellen* un déplacement (accusatif).', 4),
    ('e3dbfa87-baf6-5f35-8774-6f60429dcb1a'::uuid, '40b9ec35-d46d-57f8-bc72-9ed608b5dfd1'::uuid, '« Ich laufe im Park » signifie que je cours à l’intérieur du parc.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*in den Park* dirait que j’y entre. Ce n’est pas le verbe qui décide, mais le changement de lieu.', 5),
    ('c65f91b5-bd1b-55e2-96f4-901c8f392f5f'::uuid, '40b9ec35-d46d-57f8-bc72-9ed608b5dfd1'::uuid, 'En quoi se contracte « in das » ?', 'mcq', '["ins","im","ind","ins dem"]'::jsonb, 0, '*in dem* donne *im* : ne pas les confondre, ils n’ont pas le même cas.', 6),
    ('2ea783f0-e990-543f-b997-5be3a7b55792'::uuid, '40b9ec35-d46d-57f8-bc72-9ed608b5dfd1'::uuid, 'Comment dit-on « en janvier » ?', 'mcq', '["im Januar","in Januar","am Januar","an Januar"]'::jsonb, 0, 'Emploi figé : *im* + mois et saisons, *am* + jours et dates.', 7),
    ('30ccbd11-2050-528d-8756-0016ae6b5a94'::uuid, '40b9ec35-d46d-57f8-bc72-9ed608b5dfd1'::uuid, '« sich auf etwas freuen » se construit avec le datif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un emploi figé à l’accusatif : *Ich freue mich auf die Ferien.*', 8),
    ('7625372f-2386-57b7-a871-f1bb5ed48e75'::uuid, '042eb577-a6c3-5ee9-812d-62bf50045df6'::uuid, 'Après « denn », où se place le verbe conjugué ?', 'mcq', '["En deuxième position, comme d’habitude","À la fin de la proposition","En première position","Juste après denn"]'::jsonb, 0, '*denn* est une coordination : il ne compte pas dans l’ordre des mots.', 1),
    ('edcdf04e-544d-54f6-ba27-179a5be73ef7'::uuid, '042eb577-a6c3-5ee9-812d-62bf50045df6'::uuid, 'Quelle conjonction envoie le verbe à la fin ?', 'mcq', '["weil","denn","aber","und"]'::jsonb, 0, '*weil* subordonne ; *denn* coordonne, pour le même sens.', 2),
    ('9dca80d6-be36-51ab-9ed8-4b1ae368666e'::uuid, '042eb577-a6c3-5ee9-812d-62bf50045df6'::uuid, '« sondern » s’emploie…', 'mcq', '["Après une négation, pour rectifier","Après une affirmation","Pour exprimer la cause","Pour exprimer le but"]'::jsonb, 0, '*Das ist nicht mein Buch, sondern deins.*', 3),
    ('c7ee7c3e-1a4e-58bd-a9ce-49089313d1da'::uuid, '042eb577-a6c3-5ee9-812d-62bf50045df6'::uuid, 'Que signifie « weder… noch » ?', 'mcq', '["Ni… ni","Ou bien… ou bien","Non seulement… mais aussi","Certes… mais"]'::jsonb, 0, 'La phrase est déjà négative : on n’ajoute pas *nicht*.', 4),
    ('affd5be7-3cda-5699-9320-ee08fd85af95'::uuid, '042eb577-a6c3-5ee9-812d-62bf50045df6'::uuid, 'La virgule est obligatoire devant « aber ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme devant *sondern* et *denn* ; elle est absente devant *und* et *oder*.', 5),
    ('a805ee95-39c4-5546-b668-57859acb284d'::uuid, '042eb577-a6c3-5ee9-812d-62bf50045df6'::uuid, 'Dans « Es regnet, deshalb bleibe ich zu Hause », pourquoi « bleibe » précède-t-il « ich » ?', 'mcq', '["Parce que deshalb occupe la première position","Parce que c’est une subordonnée","Parce que deshalb est une conjonction","C’est une faute"]'::jsonb, 0, '*deshalb* est un adverbe : il prend la première place et provoque l’inversion.', 6),
    ('1964fc16-ea7a-5bc6-a949-69e283958600'::uuid, '042eb577-a6c3-5ee9-812d-62bf50045df6'::uuid, '« entweder… oder » signifie « ou bien… ou bien ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'À ne pas confondre avec *sowohl… als auch*, « aussi bien… que ».', 7),
    ('304c1a32-b35f-5a06-8513-c9a8e59b954e'::uuid, '042eb577-a6c3-5ee9-812d-62bf50045df6'::uuid, 'Quelle conjonction s’emploie sans négation devant, pour opposer ?', 'mcq', '["aber","sondern","weder","denn"]'::jsonb, 0, '*Er ist arm, aber glücklich.* *sondern* exige une négation devant lui.', 8),
    ('fc53b4ee-07b3-5293-930a-136f5d27140b'::uuid, '929714ca-d38c-5833-906b-fbd5b017287f'::uuid, 'Quelle question appelle un complément de lieu au datif ?', 'mcq', '["wo?","wohin?","woher?","wann?"]'::jsonb, 0, '*wo?* = localisation → datif. *wohin?* = déplacement → accusatif.', 1),
    ('1f0ddce7-16d5-510a-bfdf-5b75ef90798b'::uuid, '929714ca-d38c-5833-906b-fbd5b017287f'::uuid, 'Comment dit-on « je vais chez le médecin » ?', 'mcq', '["Ich gehe zum Arzt","Ich gehe beim Arzt","Ich gehe nach dem Arzt","Ich gehe in Arzt"]'::jsonb, 0, '*zu* pour la destination, *bei* pour la localisation : *beim Arzt sein*.', 2),
    ('5db549d3-6604-5db8-849c-f9e6d5cd0f53'::uuid, '929714ca-d38c-5833-906b-fbd5b017287f'::uuid, 'Comment dit-on « je viens de France » ?', 'mcq', '["Ich komme aus Frankreich","Ich komme von Frankreich","Ich komme nach Frankreich","Ich komme in Frankreich"]'::jsonb, 0, '*aus* + pays d’origine ; *von* marque un point de départ ou une personne.', 3),
    ('daeb874f-2ff3-5cf2-8938-20b1bcf68454'::uuid, '929714ca-d38c-5833-906b-fbd5b017287f'::uuid, '« nach » s’emploie devant un pays qui a un article.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec article, c’est *in* + accusatif : *in die Schweiz*, *in die Türkei*.', 4),
    ('53c40279-0a98-5c8b-953a-5df8c76318a1'::uuid, '929714ca-d38c-5833-906b-fbd5b017287f'::uuid, 'Que signifie « auf dem Land » ?', 'mcq', '["À la campagne","Sur le pays","Au bord de la mer","À l’étranger"]'::jsonb, 0, 'Et *aufs Land* pour le déplacement : *Wir fahren aufs Land.*', 5),
    ('087a3d55-865c-5731-90b4-8cb12edf6ce5'::uuid, '929714ca-d38c-5833-906b-fbd5b017287f'::uuid, 'Que marque la particule « her » ?', 'mcq', '["Le rapprochement vers le locuteur","L’éloignement du locuteur","La répétition","Le passé"]'::jsonb, 0, '*Komm her!* — *hin* marque au contraire l’éloignement.', 6),
    ('cfd3d0e4-3a22-573c-9eb7-7f8ee04cda9f'::uuid, '929714ca-d38c-5833-906b-fbd5b017287f'::uuid, '« Wo gehst du hin? » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La particule de *wohin* peut se détacher et partir en fin de phrase.', 7),
    ('22f855f5-1548-51c0-bfa6-25c45b750b16'::uuid, '929714ca-d38c-5833-906b-fbd5b017287f'::uuid, 'Comment dit-on « je rentre à la maison » ?', 'mcq', '["Ich gehe nach Hause","Ich gehe zu Hause","Ich gehe in Hause","Ich gehe im Haus"]'::jsonb, 0, '*nach Hause* pour le mouvement, *zu Hause* pour l’état.', 8),
    ('0fc2b068-11b9-56b4-90ff-5227c0f01ee9'::uuid, 'e519912f-9dab-5b64-8363-4b9049b60a99'::uuid, 'Comment dit-on « le lundi » (un lundi précis) ?', 'mcq', '["am Montag","im Montag","um Montag","in Montag"]'::jsonb, 0, '*am* + jours et parties de la journée.', 1),
    ('4972ef09-b3f3-5acf-bbce-58f87465235e'::uuid, 'e519912f-9dab-5b64-8363-4b9049b60a99'::uuid, 'Comment dit-on « en été » ?', 'mcq', '["im Sommer","am Sommer","um Sommer","in Sommer"]'::jsonb, 0, '*im* + mois, saisons et années.', 2),
    ('9edd0611-cfd3-5c32-a3e1-f050c58a7329'::uuid, 'e519912f-9dab-5b64-8363-4b9049b60a99'::uuid, 'Comment dit-on « à huit heures » ?', 'mcq', '["um acht Uhr","am acht Uhr","im acht Uhr","in acht Uhr"]'::jsonb, 0, '*um* + heure précise.', 3),
    ('76636c39-31f7-5544-8659-b30e9f1bb695'::uuid, 'e519912f-9dab-5b64-8363-4b9049b60a99'::uuid, '« jeden Tag » est au…', 'mcq', '["Accusatif, sans préposition","Datif, sans préposition","Génitif","Nominatif"]'::jsonb, 0, 'Durées et dates entières se mettent à l’accusatif nu : *letzte Woche*, *den ganzen Tag*.', 4),
    ('daa6fc61-86e2-5c16-855d-263b828605d8'::uuid, 'e519912f-9dab-5b64-8363-4b9049b60a99'::uuid, 'Comment dit-on « il y a deux semaines » ?', 'mcq', '["vor zwei Wochen","seit zwei Wochen","in zwei Wochen","ab zwei Wochen"]'::jsonb, 0, '*vor* + datif pour le passé ; *in* + datif pour le futur.', 5),
    ('cf049d47-507c-5e1f-9f22-24a0449a4185'::uuid, 'e519912f-9dab-5b64-8363-4b9049b60a99'::uuid, '« morgens » signifie « demain ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*morgen* = demain, *morgens* = le matin (habituellement).', 6),
    ('a1d27af5-6f16-5fd7-9efe-8d6aba421d31'::uuid, 'e519912f-9dab-5b64-8363-4b9049b60a99'::uuid, 'Quelle préposition régit le génitif ?', 'mcq', '["während","seit","ab","bis"]'::jsonb, 0, '*während der Ferien*, *während des Sommers*.', 7),
    ('73810449-96f5-5996-a9b1-e20596abd1e6'::uuid, 'e519912f-9dab-5b64-8363-4b9049b60a99'::uuid, 'Où se place le complément de temps parmi les compléments ?', 'mcq', '["En premier","En dernier","Après le lieu","Après la manière"]'::jsonb, 0, 'C’est le *Te* de TeKaMoLo : temps, cause, manière, lieu.', 8),
    ('5788abaa-d6dd-5e43-8e87-9c2b8497e82d'::uuid, '58c0acea-592c-566e-9bd1-d2c6df4c8c14'::uuid, 'Quel auxiliaire s’emploie au parfait avec les verbes de mouvement ?', 'mcq', '["sein","haben","werden","lassen"]'::jsonb, 0, '*Ich bin gefahren*, *ich bin gegangen*.', 1),
    ('08501e9e-f846-518f-8e09-36eeab5fee10'::uuid, '58c0acea-592c-566e-9bd1-d2c6df4c8c14'::uuid, 'Quel est le prétérit de « haben » à la 1re personne ?', 'mcq', '["ich hatte","ich habte","ich hatt","ich war"]'::jsonb, 0, 'Verbe mixte : radical modifié + terminaison faible.', 2),
    ('5150cc36-9fb2-5071-92a9-cbba8eab7b80'::uuid, '58c0acea-592c-566e-9bd1-d2c6df4c8c14'::uuid, '« werden » sert d’auxiliaire au futur ET au passif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ich werde kommen* (futur) / *Das Haus wird gebaut* (passif).', 3),
    ('a2438c77-96b7-5282-9720-b7f2d307f4c0'::uuid, '58c0acea-592c-566e-9bd1-d2c6df4c8c14'::uuid, 'Comment se conjugue « sein » à la 2e personne du pluriel ?', 'mcq', '["ihr seid","ihr sind","ihr seit","ihr bist"]'::jsonb, 0, '*seid* avec un d — *seit* avec un t est la préposition « depuis ».', 4),
    ('f49913cc-1cd3-56a9-8563-a772264e532c'::uuid, '58c0acea-592c-566e-9bd1-d2c6df4c8c14'::uuid, 'Que signifie « bekommen » ?', 'mcq', '["Recevoir","Devenir","Venir","Convenir"]'::jsonb, 0, 'Faux ami classique : « devenir » se dit *werden*.', 5),
    ('7c2c86c8-e967-5a48-9552-abd70a98c9a7'::uuid, '58c0acea-592c-566e-9bd1-d2c6df4c8c14'::uuid, '« Ich habe das Auto gefahren » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Employé avec un COD, un verbe de mouvement prend *haben*.', 6),
    ('f22a9ce3-a27f-5c1c-9e89-a59a48a49a9a'::uuid, '58c0acea-592c-566e-9bd1-d2c6df4c8c14'::uuid, 'Quel est le participe passé de « werden » dans un passif ?', 'mcq', '["worden","geworden","gewerdet","werdet"]'::jsonb, 0, '*geworden* est réservé au verbe plein : *Er ist Arzt geworden.*', 7),
    ('850676e5-9144-5085-9e7b-babea149964c'::uuid, '58c0acea-592c-566e-9bd1-d2c6df4c8c14'::uuid, 'Quel auxiliaire prend « bleiben » au parfait ?', 'mcq', '["sein","haben","werden","les deux au choix"]'::jsonb, 0, '*Ich bin zu Hause geblieben*, comme *sein* et *passieren*.', 8),
    ('848e3495-934c-51f6-b0f3-c5afb8812568'::uuid, '144b1215-3f83-5520-b96b-21d2d4c7dd33'::uuid, 'Qu’appelle-t-on les trois temps primitifs d’un verbe ?', 'mcq', '["Infinitif, prétérit, participe II","Présent, futur, passé","Infinitif, présent, parfait","Radical, préverbe, terminaison"]'::jsonb, 0, 'Avec eux, toute la conjugaison se déduit.', 1),
    ('179e9af2-7f9e-52fb-a330-4084d44ab9ec'::uuid, '144b1215-3f83-5520-b96b-21d2d4c7dd33'::uuid, 'Quel est le participe passé de « spielen » ?', 'mcq', '["gespielt","gespielen","spielte","gespiel"]'::jsonb, 0, 'Verbe faible : *ge-* + radical + *-t*.', 2),
    ('62518e68-f72e-5d84-b3d2-d00471c25871'::uuid, '144b1215-3f83-5520-b96b-21d2d4c7dd33'::uuid, 'Un verbe fort change de voyelle au prétérit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’alternance vocalique : *sprechen → sprach*, *fahren → fuhr*.', 3),
    ('3f47cf9c-9d4c-5fee-84cf-128948dffdf0'::uuid, '144b1215-3f83-5520-b96b-21d2d4c7dd33'::uuid, 'Comment se conjugue « geben » à la 3e personne du singulier ?', 'mcq', '["er gibt","er gebt","er gab","er gibst"]'::jsonb, 0, 'Alternance *e → i* aux 2e et 3e personnes du singulier seulement.', 4),
    ('67b6842a-6484-5d34-8812-b32ad2450544'::uuid, '144b1215-3f83-5520-b96b-21d2d4c7dd33'::uuid, 'Comment se conjugue « fahren » à la 2e personne du singulier ?', 'mcq', '["du fährst","du fahrst","du fuhrst","du fährt"]'::jsonb, 0, 'Alternance *a → ä*, qui disparaît au pluriel.', 5),
    ('29d1229f-1ce0-5ede-af4c-aa7b82004926'::uuid, '144b1215-3f83-5520-b96b-21d2d4c7dd33'::uuid, '« bringen → brachte → gebracht » est un verbe…', 'mcq', '["Mixte","Faible régulier","Fort","Irrégulier isolé"]'::jsonb, 0, 'Radical modifié mais terminaisons faibles, comme *denken* et *wissen*.', 6),
    ('17bdf5e1-26b0-5742-9292-4f1078c0037f'::uuid, '144b1215-3f83-5520-b96b-21d2d4c7dd33'::uuid, 'Les verbes en -ieren prennent « ge- » au participe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*studiert*, *telefoniert*, *fotografiert* : jamais de *ge-*.', 7),
    ('38be539c-9272-5079-b26b-969932520617'::uuid, '144b1215-3f83-5520-b96b-21d2d4c7dd33'::uuid, 'Quel est le prétérit de « schreiben » ?', 'mcq', '["schrieb","schreibte","schrob","geschrieben"]'::jsonb, 0, 'Verbe fort : *schreiben → schrieb → geschrieben*.', 8),
    ('d95cec72-ba16-51ee-91e7-79c25daa6d4a'::uuid, '3d223955-2ecb-5a62-bb2e-77240ae441ec'::uuid, 'Où se place l’infinitif dépendant d’un modal, dans une principale ?', 'mcq', '["À la fin de la phrase","Juste après le modal","Devant le sujet","En première position"]'::jsonb, 0, '*Ich muss heute Abend arbeiten.*', 1),
    ('82844d1f-6a73-5790-baa8-83e9f11da5f1'::uuid, '3d223955-2ecb-5a62-bb2e-77240ae441ec'::uuid, 'Comment se conjugue « können » à la 1re personne du singulier ?', 'mcq', '["ich kann","ich könne","ich kanne","ich könnt"]'::jsonb, 0, 'Les modaux n’ont aucune terminaison aux 1re et 3e personnes du singulier.', 2),
    ('6105d7e3-c8e2-5a4c-b868-6a16f5b206c0'::uuid, '3d223955-2ecb-5a62-bb2e-77240ae441ec'::uuid, '« Ich muss nicht kommen » signifie…', 'mcq', '["Je ne suis pas obligé de venir","Je ne dois pas venir","Je ne peux pas venir","Je ne veux pas venir"]'::jsonb, 0, 'L’interdiction se dit *nicht dürfen* : *Du darfst nicht kommen.*', 3),
    ('5094bded-cede-58e9-8da6-52d538b50639'::uuid, '3d223955-2ecb-5a62-bb2e-77240ae441ec'::uuid, 'Quel modal exprime une consigne venue d’autrui ?', 'mcq', '["sollen","wollen","können","mögen"]'::jsonb, 0, '*Ich soll den Arzt fragen* : on m’a dit de le faire.', 4),
    ('15cf22c5-70a1-5e7d-8a97-11336cb23a25'::uuid, '3d223955-2ecb-5a62-bb2e-77240ae441ec'::uuid, 'Quel est le prétérit de « müssen » ?', 'mcq', '["musste","müsste","mochte","gemusst"]'::jsonb, 0, 'Sans inflexion : *musste*. *müsste* est le subjonctif II.', 5),
    ('815bc93e-b672-5aa0-92a2-4195bc8f2751'::uuid, '3d223955-2ecb-5a62-bb2e-77240ae441ec'::uuid, 'Au parfait, avec un infinitif dépendant, le modal prend la forme du participe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le double infinitif : *Ich habe arbeiten müssen.*', 6),
    ('3312ebf7-c69f-54a3-875c-f1fe4c521461'::uuid, '3d223955-2ecb-5a62-bb2e-77240ae441ec'::uuid, 'Comment dire poliment « je voudrais un café » ?', 'mcq', '["Ich möchte einen Kaffee","Ich will einen Kaffee","Ich mag einen Kaffee","Ich muss einen Kaffee"]'::jsonb, 0, '*möchte* est le subjonctif II de *mögen* : la forme polie usuelle.', 7),
    ('70cb56a3-8798-5e99-b9e2-d847a7e6e73d'::uuid, '3d223955-2ecb-5a62-bb2e-77240ae441ec'::uuid, 'Quel modal exprime l’autorisation ?', 'mcq', '["dürfen","müssen","wollen","sollen"]'::jsonb, 0, '*Darf ich reinkommen?* — *können* dit la capacité.', 8),
    ('0d73f3f4-f87e-5128-b33d-39e4b22fb3e6'::uuid, '2262badd-8fd2-53fc-a855-123ee0cd4b5c'::uuid, 'Comment reconnaître un préverbe séparable ?', 'mcq', '["Il porte l’accent du mot","Il commence par be-","Il se termine par -en","Il est toujours plus long"]'::jsonb, 0, '*ÁNrufen* contre *be-SÚCHEN* : le critère s’entend.', 1),
    ('10a1e540-bec4-57ef-954d-b35fa40b86bf'::uuid, '2262badd-8fd2-53fc-a855-123ee0cd4b5c'::uuid, 'Dans une principale, où va le préverbe séparable ?', 'mcq', '["À la fin de la phrase","Devant le verbe","Après le sujet","Il reste soudé"]'::jsonb, 0, '*Ich stehe um sieben Uhr auf.*', 2),
    ('2585ba12-e37b-565c-b81d-d49547ebf44e'::uuid, '2262badd-8fd2-53fc-a855-123ee0cd4b5c'::uuid, 'Quel est le participe passé de « aufstehen » ?', 'mcq', '["aufgestanden","geaufstanden","aufstanden","gestandenauf"]'::jsonb, 0, 'Le *ge-* s’intercale entre le préverbe et le radical.', 3),
    ('de115747-c322-5a08-bfd0-0b2b47754bcb'::uuid, '2262badd-8fd2-53fc-a855-123ee0cd4b5c'::uuid, 'Quel est le participe passé de « besuchen » ?', 'mcq', '["besucht","gebesucht","besuchen","gesucht"]'::jsonb, 0, 'Les préverbes inséparables (*be-, ver-, er-, ent-*) interdisent le *ge-*.', 4),
    ('88d10935-c07b-5972-8184-d789d2ff228d'::uuid, '2262badd-8fd2-53fc-a855-123ee0cd4b5c'::uuid, 'Comment écrit-on « einkaufen » avec « zu » ?', 'mcq', '["einzukaufen","zu einkaufen","einkaufen zu","zueinkaufen"]'::jsonb, 0, 'Le *zu* s’intercale, et le tout s’écrit en un seul mot.', 5),
    ('d7722c06-7349-5f2e-abb6-67d48bff5617'::uuid, '2262badd-8fd2-53fc-a855-123ee0cd4b5c'::uuid, 'En subordonnée, le préverbe reste détaché.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le verbe conjugué part à la fin et rejoint son préverbe : *…, weil er aufsteht.*', 6),
    ('42d20c18-7527-5b6b-b12f-5f858a6c96df'::uuid, '2262badd-8fd2-53fc-a855-123ee0cd4b5c'::uuid, '« übersetzen » est toujours inséparable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Séparable au sens concret (traverser), inséparable au sens figuré (traduire).', 7),
    ('8fcc8006-2d4e-5432-9d08-f5c3a4a29f36'::uuid, '2262badd-8fd2-53fc-a855-123ee0cd4b5c'::uuid, 'Que signifie « ankommen » ?', 'mcq', '["Arriver","Venir","Recevoir","Accompagner"]'::jsonb, 0, '*bekommen* = recevoir, *mitkommen* = accompagner : le préverbe fait le sens.', 8),
    ('d38a9729-80a5-57f4-9563-8b2281a8c07d'::uuid, 'ea5747a4-89ec-5daf-be9c-846ea8fabecc'::uuid, 'Quelle est la forme du réfléchi à la 3e personne, à l’accusatif comme au datif ?', 'mcq', '["sich","ihn","ihm","es"]'::jsonb, 0, '*sich* couvre les deux cas à la 3e personne, singulier et pluriel.', 1),
    ('bdd75695-6c96-5057-a196-3e953c8435f8'::uuid, 'ea5747a4-89ec-5daf-be9c-846ea8fabecc'::uuid, 'Quand emploie-t-on le réfléchi au datif ?', 'mcq', '["Quand la phrase contient déjà un COD","Quand le verbe est fort","Quand la phrase est négative","Quand le sujet est au pluriel"]'::jsonb, 0, '*Ich wasche mir die Hände* : *die Hände* est le COD.', 2),
    ('5daa8194-2966-5603-b5bc-85477036a08a'::uuid, 'ea5747a4-89ec-5daf-be9c-846ea8fabecc'::uuid, 'Comment dit-on « je me lave » (sans complément) ?', 'mcq', '["Ich wasche mich","Ich wasche mir","Ich wasche mich die","Ich wasche sich"]'::jsonb, 0, 'Sans COD, le réfléchi reste à l’accusatif.', 3),
    ('4fc290c2-e2d4-5418-90b1-dde26a22d0a2'::uuid, 'ea5747a4-89ec-5daf-be9c-846ea8fabecc'::uuid, 'Où se place le pronom réfléchi dans une principale ?', 'mcq', '["Juste après le verbe conjugué","À la fin de la phrase","Devant le sujet toujours","Après le participe passé"]'::jsonb, 0, '*Ich freue mich auf die Ferien.*', 4),
    ('08394bb3-19d1-5315-8e41-7d4a3239a60d'::uuid, 'ea5747a4-89ec-5daf-be9c-846ea8fabecc'::uuid, '« sich freuen auf » se construit avec…', 'mcq', '["L’accusatif","Le datif","Le génitif","Le nominatif"]'::jsonb, 0, 'Comme *sich interessieren für* et *sich erinnern an* : préposition + accusatif.', 5),
    ('470dacaa-94e5-5e28-a7b2-858fe540202e'::uuid, 'ea5747a4-89ec-5daf-be9c-846ea8fabecc'::uuid, '« aufstehen » est un verbe pronominal en allemand.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Se lever » se dit *aufstehen*, sans pronom réfléchi.', 6),
    ('40cdb27d-2a6c-5151-8720-5d7c4925e659'::uuid, 'ea5747a4-89ec-5daf-be9c-846ea8fabecc'::uuid, 'Dans le vouvoiement, « sich » prend une majuscule.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Setzen Sie sich bitte!* — seul *Sie* et ses formes possessives la prennent.', 7),
    ('68ab6f2e-e3ae-5735-83ab-ab70f7589f5b'::uuid, 'ea5747a4-89ec-5daf-be9c-846ea8fabecc'::uuid, 'Comment dit-on « je m’achète un livre » ?', 'mcq', '["Ich kaufe mir ein Buch","Ich kaufe mich ein Buch","Ich kaufe sich ein Buch","Ich kaufe mein Buch"]'::jsonb, 0, 'Il y a un COD (*ein Buch*) : le réfléchi passe au datif.', 8),
    ('93676ac6-438b-5420-9997-fc93ffcde7d3'::uuid, 'da650db0-9662-5d6b-a422-755348cf21b9'::uuid, 'Quelle est la terminaison de la 2e personne du singulier ?', 'mcq', '["-st","-t","-e","-en"]'::jsonb, 0, '*du spielst*, *du lernst*, *du wohnst*.', 1),
    ('6a8b8bb6-31e4-5f54-8a74-b2ab21fd8188'::uuid, 'da650db0-9662-5d6b-a422-755348cf21b9'::uuid, 'Comment se conjugue « arbeiten » à la 3e personne du singulier ?', 'mcq', '["er arbeitet","er arbeitt","er arbeit","er arbeitest"]'::jsonb, 0, 'Radical en *-t* : on intercale un *e* pour pouvoir prononcer.', 2),
    ('af80d206-c67f-5055-9143-0f8deeafb480'::uuid, 'da650db0-9662-5d6b-a422-755348cf21b9'::uuid, 'Comment se conjugue « heißen » à la 2e personne du singulier ?', 'mcq', '["du heißt","du heißst","du heißest","du heißen"]'::jsonb, 0, 'Après *-s, -ß, -z*, le *-st* perd son *s*.', 3),
    ('c008f562-963f-519e-90d6-b53747d28913'::uuid, 'da650db0-9662-5d6b-a422-755348cf21b9'::uuid, 'Le changement de voyelle des verbes forts touche aussi le pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ne concerne que les 2e et 3e personnes du singulier : *wir fahren*, pas *wir fähren*.', 4),
    ('8442d261-7cb5-520e-adca-696ac895d4d4'::uuid, 'da650db0-9662-5d6b-a422-755348cf21b9'::uuid, 'Comment se conjugue « lesen » à la 3e personne du singulier ?', 'mcq', '["er liest","er lest","er läst","er liesst"]'::jsonb, 0, 'Alternance *e → ie*, et le *-st* fusionne avec le *s* du radical.', 5),
    ('eea02898-0468-56f3-b6b9-946f56c4dd67'::uuid, 'da650db0-9662-5d6b-a422-755348cf21b9'::uuid, 'Comment traduire « demain, je vais à Berlin » ?', 'mcq', '["Morgen fahre ich nach Berlin","Morgen ich fahre nach Berlin","Morgen werde ich fahren nach Berlin","Morgen ich werde nach Berlin"]'::jsonb, 0, 'Le présent suffit à dire l’avenir dès qu’un adverbe de temps le précise.', 6),
    ('460fa175-8333-5729-a2a9-ae3408e5d3b6'::uuid, 'da650db0-9662-5d6b-a422-755348cf21b9'::uuid, 'Avec « seit », l’allemand emploie le parfait.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le présent : *Ich lerne seit drei Jahren Deutsch.*', 7),
    ('cec3e642-c365-52d2-9b1f-4ef55e4f2cae'::uuid, 'da650db0-9662-5d6b-a422-755348cf21b9'::uuid, 'Comment se conjugue « werden » à la 2e personne du singulier ?', 'mcq', '["du wirst","du werdest","du werdst","du wird"]'::jsonb, 0, '*werde, wirst, wird, werden, werdet, werden*.', 8),
    ('1c823c69-7949-5bbd-8b5c-7e7a65726578'::uuid, 'c6003b04-cec0-5d30-a914-f33dd58de659'::uuid, 'Le prétérit est le temps…', 'mcq', '["De l’écrit et du récit","De l’oral courant","Du futur proche","De l’hypothèse"]'::jsonb, 0, 'À l’oral, on raconte au parfait — sauf pour *sein*, *haben* et les modaux.', 1),
    ('d88e8d73-5a71-57c0-aa88-f30d07fbe7b6'::uuid, 'c6003b04-cec0-5d30-a914-f33dd58de659'::uuid, 'Quelle est la marque du prétérit des verbes faibles ?', 'mcq', '["-te","-en","-st","Un changement de voyelle"]'::jsonb, 0, '*ich spielte*, *er spielte* : les deux formes sont identiques.', 2),
    ('7b27d51d-33a1-5241-ad60-d53da1d67b16'::uuid, 'c6003b04-cec0-5d30-a914-f33dd58de659'::uuid, 'Quel est le prétérit de « gehen » ?', 'mcq', '["ging","gehte","gang","gegangen"]'::jsonb, 0, 'Verbe fort : *gehen → ging → gegangen*.', 3),
    ('8fe68ed6-e494-5338-b15c-d3608dae4043'::uuid, 'c6003b04-cec0-5d30-a914-f33dd58de659'::uuid, 'Aux 1re et 3e personnes, un verbe fort au prétérit ne prend aucune terminaison.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*ich ging*, *er ging* : la forme est nue.', 4),
    ('7e5383df-e3fc-5b45-bf48-6f43c9b1fe73'::uuid, 'c6003b04-cec0-5d30-a914-f33dd58de659'::uuid, 'Quel est le prétérit de « wissen » ?', 'mcq', '["wusste","wisste","wieß","gewusst"]'::jsonb, 0, 'Verbe mixte : radical modifié, terminaison faible.', 5),
    ('73b72692-7277-5457-8f92-1afd0b8c1578'::uuid, 'c6003b04-cec0-5d30-a914-f33dd58de659'::uuid, 'Quels verbes emploie-t-on au prétérit même à l’oral ?', 'mcq', '["sein, haben, werden et les modaux","Tous les verbes forts","Les verbes en -ieren","Aucun"]'::jsonb, 0, '*Ich war müde* est bien plus naturel que *ich bin müde gewesen*.', 6),
    ('3279afd8-d913-5754-84ee-22d6d01f11f3'::uuid, 'c6003b04-cec0-5d30-a914-f33dd58de659'::uuid, 'Comment forme-t-on le plus-que-parfait ?', 'mcq', '["Prétérit de haben ou sein + participe II","Présent de werden + infinitif","Prétérit + zu","Parfait + würde"]'::jsonb, 0, '*Ich hatte gegessen*, *er war gegangen* — surtout après *nachdem*.', 7),
    ('9b4a73cc-d57e-5d18-ae9d-50e794c4e9e9'::uuid, 'c6003b04-cec0-5d30-a914-f33dd58de659'::uuid, 'Quel est le prétérit de « nehmen » ?', 'mcq', '["nahm","nehmte","nimmte","genommen"]'::jsonb, 0, 'Alternance forte : *nehmen → nahm → genommen*.', 8),
    ('38d0390f-8742-5c13-a64a-6f16935e569e'::uuid, '824b2b34-15d9-54fb-bad4-6b8a170baeb4'::uuid, 'Où se place le participe II dans une principale au parfait ?', 'mcq', '["À la fin de la phrase","Juste après l’auxiliaire","En deuxième position","Devant le sujet"]'::jsonb, 0, 'C’est la parenthèse verbale : l’auxiliaire ouvre, le participe ferme.', 1),
    ('d690edac-5e72-5337-8177-cbdc3e280f35'::uuid, '824b2b34-15d9-54fb-bad4-6b8a170baeb4'::uuid, 'Quel est le participe II de « fahren » ?', 'mcq', '["gefahren","gefahrt","fahren","gefuhr"]'::jsonb, 0, 'Verbe fort : *ge-* + radical + *-en*.', 2),
    ('2e44938f-1111-5c33-9197-3ce2229d0060'::uuid, '824b2b34-15d9-54fb-bad4-6b8a170baeb4'::uuid, 'Quel auxiliaire prend « einschlafen » au parfait ?', 'mcq', '["sein","haben","werden","Les deux"]'::jsonb, 0, 'C’est un verbe de changement d’état : *Ich bin eingeschlafen.*', 3),
    ('ab902d0c-a852-521c-b12f-a1768fad11e4'::uuid, '824b2b34-15d9-54fb-bad4-6b8a170baeb4'::uuid, 'Quel est le participe II de « telefonieren » ?', 'mcq', '["telefoniert","getelefoniert","telefonierte","getelefonierte"]'::jsonb, 0, 'Les verbes en *-ieren* n’ont jamais de *ge-*.', 4),
    ('7fb8eda7-1dd7-5355-8cc0-dd0fe1e617d0'::uuid, '824b2b34-15d9-54fb-bad4-6b8a170baeb4'::uuid, 'Quel est le participe II de « einkaufen » ?', 'mcq', '["eingekauft","geeinkauft","einkauft","gekaufein"]'::jsonb, 0, 'Préverbe séparable : le *ge-* s’intercale.', 5),
    ('4d29ddd6-d6ba-51c3-876e-85e3ae3a347c'::uuid, '824b2b34-15d9-54fb-bad4-6b8a170baeb4'::uuid, '« Ich habe das Auto gefahren » est une faute.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Employé avec un COD, *fahren* prend *haben*.', 6),
    ('d0cb21ef-35f4-5d6f-9322-fbcb4e96259f'::uuid, '824b2b34-15d9-54fb-bad4-6b8a170baeb4'::uuid, 'En subordonnée, où se place l’auxiliaire au parfait ?', 'mcq', '["Après le participe, à la toute fin","En deuxième position","Devant le participe","Il disparaît"]'::jsonb, 0, '*…, weil ich einen Film gesehen habe.*', 7),
    ('b39f873f-5973-5624-a112-0492ce836ef5'::uuid, '824b2b34-15d9-54fb-bad4-6b8a170baeb4'::uuid, 'Le parfait est le passé de la conversation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le prétérit, lui, est celui du récit écrit.', 8),
    ('2518bf38-6151-5e15-8698-2e8eef9f07cc'::uuid, 'c224b106-f992-5af0-8990-d0d991f64487'::uuid, 'Comment se forme le Futur I ?', 'mcq', '["werden + infinitif","sein + participe II","haben + infinitif","werden + participe II"]'::jsonb, 0, '*Ich werde morgen fahren*, l’infinitif en fin de phrase.', 1),
    ('9670ce0f-7bd7-5c7a-a37c-b7463f78dc56'::uuid, 'c224b106-f992-5af0-8990-d0d991f64487'::uuid, 'Comment se conjugue « werden » à la 3e personne du singulier ?', 'mcq', '["er wird","er werd","er werdet","er wurde"]'::jsonb, 0, '*ich werde, du wirst, er wird…*', 2),
    ('6b75d774-141c-54c0-aa8e-cf7d3c5c65d5'::uuid, 'c224b106-f992-5af0-8990-d0d991f64487'::uuid, 'Quand le présent suffit-il à exprimer le futur ?', 'mcq', '["Quand un adverbe de temps précise l’avenir","Jamais","Uniquement avec les modaux","Uniquement à l’écrit"]'::jsonb, 0, '*Morgen fahre ich nach Berlin* est la forme la plus courante.', 3),
    ('94b0d527-1ec0-5905-9e7f-1e411233ba9e'::uuid, 'c224b106-f992-5af0-8990-d0d991f64487'::uuid, '« Er wird wohl krank sein » signifie…', 'mcq', '["Il doit être malade (supposition)","Il sera malade demain","Il est tombé malade","Il veut être malade"]'::jsonb, 0, 'Le futur exprime aussi une hypothèse sur le présent, souvent avec *wohl*.', 4),
    ('2f7c27d6-9ea2-5bc6-a607-87aba55487db'::uuid, 'c224b106-f992-5af0-8990-d0d991f64487'::uuid, '« Das Haus wird gebaut » est un futur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un passif : *werden* + participe II. Le futur demanderait un infinitif.', 5),
    ('4fc921c2-0eec-5687-9b0b-58c13c27cbd8'::uuid, 'c224b106-f992-5af0-8990-d0d991f64487'::uuid, 'Que signifie « Er wird Arzt » ?', 'mcq', '["Il devient médecin","Il sera médecin demain","Il est fait médecin","Il doit être médecin"]'::jsonb, 0, '*werden* + nom : c’est le verbe plein « devenir ».', 6),
    ('7ca9a1c3-8fcb-5037-bf0a-5177d48d7ccd'::uuid, 'c224b106-f992-5af0-8990-d0d991f64487'::uuid, 'En subordonnée, quel mot ferme une phrase au futur ?', 'mcq', '["werden conjugué","L’infinitif","Le sujet","La conjonction"]'::jsonb, 0, '*…, dass er kommen wird.*', 7),
    ('964e3246-ae13-559b-aa79-3028b798e148'::uuid, 'c224b106-f992-5af0-8990-d0d991f64487'::uuid, 'Le Futur II exprime une action achevée dans l’avenir.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Bis morgen werde ich das Buch gelesen haben* — ou une supposition sur le passé.', 8),
    ('81c9fa1b-8074-50df-af22-c2fffea0a808'::uuid, '3afe8e68-f0c5-5848-ac9c-276ad4d40aa4'::uuid, 'Quelle est la forme d’impératif de « kommen » pour « du » ?', 'mcq', '["Komm!","Kommst!","Komme du!","Kommen!"]'::jsonb, 0, 'Radical sans terminaison et sans pronom.', 1),
    ('e4a075ec-cb2c-57cb-908e-eb0f3915c7d5'::uuid, '3afe8e68-f0c5-5848-ac9c-276ad4d40aa4'::uuid, 'Comment dit-on « Donne ! » (du) ?', 'mcq', '["Gib!","Geb!","Gebe!","Gibst!"]'::jsonb, 0, 'L’alternance *e → i* se maintient à l’impératif.', 2),
    ('98f1f420-d9cc-52a4-8dcf-3a67485e853d'::uuid, '3afe8e68-f0c5-5848-ac9c-276ad4d40aa4'::uuid, '« Fahre! » garde-t-il l’inflexion de « du fährst » ?', 'mcq', '["Non, on dit Fahr!","Oui, on dit Fähr!","Oui, on dit Fährst!","Les deux sont possibles"]'::jsonb, 0, 'L’alternance *a → ä* disparaît à l’impératif.', 3),
    ('f90ee065-e5a8-5837-8cf0-568b0974f9ba'::uuid, '3afe8e68-f0c5-5848-ac9c-276ad4d40aa4'::uuid, 'À la forme de politesse, le pronom « Sie » se maintient.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Kommen Sie!*, *Setzen Sie sich!* — contrairement aux formes du *du* et du *ihr*.', 4),
